"use client";

import React, { useState, useEffect } from "react";
import { getAttention, updateAttention } from "@/lib/adapters";
import { useAdapter } from "@/hooks/useAdapter";
import { AttentionData, ContentIdea, MarketSignal } from "@/lib/types";

import { Card, CardTitle, CardHeader } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { FormField, Input, Select, Textarea } from "@/components/ui/Forms";
import { Badge } from "@/components/ui/Badge";
import { Skeleton, CardSkeleton } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { Tabs } from "@/components/ui/Tabs";

export default function AttentionPage() {
  const { data, setData, localData, setLocalData, loading, error, reload: loadData } = useAdapter(getAttention);

  // Tab states
  const [activeTab, setActiveTab] = useState("overview");

  // Script Builder Context
  const [activeIdeaId, setActiveIdeaId] = useState<string | null>(null);
  const [isDrafting, setIsDrafting] = useState(false);
  const [draftSuccess, setDraftSuccess] = useState(false);
  const [isApproving, setIsApproving] = useState(false);

  async function handleAIBuildTrigger(ideaId: string) {
    const idea = localData?.ideas.find(i => i.id === ideaId);
    if (!idea) return;

    // Transition state strictly to drafting visually
    setLocalData(prev => prev ? ({ ...prev, ideas: prev.ideas.map(i => i.id === ideaId ? { ...i, status: "drafting" } : i) }) : prev);
    setIsDrafting(true);

    // Simulate AI networking delay securely
    await new Promise(r => setTimeout(r, 2000));

    // Generate deterministic drafted content using configuration parameters explicitly
    const generatedDraft = `[GENERATED SYSTEM DRAFT]
Title: ${idea.title || "Untitled"}
Vector: ${idea.stage}
Framework: ${idea.framework}

ANGLE INJECTION:
${idea.angle || "No explicit angle mapped. Following standard framework logic."}

OUTPUT GOAL:
${idea.outputGoal || "Drive general pipeline awareness."}

--- SCRIPT DRAFT ---
We noticed an opportunity in the market matching your parameters. Utilizing the ${idea.framework} framework, this asset is designed to natively capture attention at the ${idea.stage} maturity level. 

Given your defined angle, the draft pivots securely resolving against your Founder Voice cadence securely.

Please edit this mock context strictly before approving it for the production pipeline.`;

    // Mutate state securely to requires_review mapping the generated output properly.
    setLocalData(prev => prev ? ({ ...prev, ideas: prev.ideas.map(i => i.id === ideaId ? { ...i, status: "requires_review", contentDraft: generatedDraft } : i) }) : prev);

    setIsDrafting(false);
    setDraftSuccess(true);
    setTimeout(() => setDraftSuccess(false), 3000);
  }

  async function handleApprove(ideaId: string) {
    if (!localData) return;
    setIsApproving(true);
    try {
      const payload = {
        ...localData,
        ideas: localData.ideas.map(i => i.id === ideaId ? { ...i, status: "approved" as const } : i)
      };

      const res = await updateAttention(payload); // Adapter boundary enforcement
      setData(res);
      setLocalData(res);
    } catch (err: unknown) {
      alert("Failed to approve. " + (err instanceof Error ? err.message : String(err)));
    } finally {
      setIsApproving(false);
    }
  }

  async function handleIdeaFieldChange(id: string, field: keyof ContentIdea, value: string) {
    setLocalData(prev => {
      if (!prev) return prev;
      const mutatedIdeas = prev.ideas.map(idea => idea.id === id ? { ...idea, [field]: value } : idea);
      return { ...prev, ideas: mutatedIdeas };
    });
  }

  // Active Idea strictly bounded via localData pointer
  const activeIdea = localData?.ideas.find(i => i.id === activeIdeaId);

  if (loading) {
    return (
      <div className="p-6 md:p-8 lg:p-12 max-w-[1240px] mx-auto animate-in fade-in duration-300">
        <Skeleton className="h-8 w-64 mb-2" />
        <Skeleton className="h-4 w-48 mb-8" />
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 space-y-6">
            <CardSkeleton />
          </div>
          <div><CardSkeleton /></div>
        </div>
      </div>
    );
  }

  if (error || !data || !localData) {
    return (
      <div className="p-6 md:p-8 lg:p-12 max-w-[1240px] mx-auto">
        <Alert variant="danger" title="Engine Offline">
          {error || "Attention engine could not initialize."}
          <div className="mt-4">
            <Button variant="secondary" size="sm" onClick={loadData}>Restart Engine</Button>
          </div>
        </Alert>
      </div>
    );
  }

  const tabs = [
    { id: "overview", label: "Workload Overview" },
    { id: "opportunities", label: "Market Intelligence" },
    { id: "script_builder", label: "Script Builder" },
  ];

  // Derive workflow stats safely from exact type parameters
  const ideaCount = localData.ideas.filter(i => i.status === "idea").length;
  const draftCount = localData.ideas.filter(i => i.status === "drafting").length;
  const reviewCount = localData.ideas.filter(i => i.status === "requires_review").length;

  const getStageColor = (stage: string) => {
    switch (stage) {
      case "TOF": return "primary";
      case "MOF": return "warning";
      case "BOF": return "success";
      default: return "neutral";
    }
  };

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-[1240px] mx-auto">

      {/* HEADER */}
      <header className="mb-8">
        <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <h1 className="text-3xl lg:text-[40px] font-display font-bold text-on-surface tracking-tight uppercase">
                Attention
              </h1>
              <Badge variant="primary" size="sm">Organic Growth</Badge>
            </div>
            <p className="text-on-surface-variant text-[14.5px] font-medium max-w-2xl leading-relaxed">
              Generate predictable demand through automated architecture. Map opportunities, frame scripts using corporate DNA, and review drafted pipelines.
            </p>
          </div>
          <Card variant="outlined" className="min-w-[200px]">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-display font-medium text-[12px] text-on-surface-variant uppercase tracking-widest">Pending Review</h3>
              <Badge variant={reviewCount > 0 ? "warning" : "neutral"} size="sm">{reviewCount}</Badge>
            </div>
            <Button variant="primary" size="sm" className="w-full mt-2" onClick={() => setActiveTab("script_builder")} disabled={reviewCount === 0}>
              Begin Approvals
            </Button>
          </Card>
        </div>
      </header>

      {/* NAVIGATION TABS */}
      <div className="mb-6 border-b border-outline-variant">
        <Tabs tabs={tabs} activeTab={activeTab} onChange={setActiveTab} />
      </div>

      <div className="animate-in fade-in duration-300">

        {/* OVERVIEW PANEL */}
        {activeTab === "overview" && (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

            {/* Main Workload Columns */}
            <div className="lg:col-span-2 space-y-6">

              <Card>
                <CardHeader>
                  <CardTitle>Content Lifecycle</CardTitle>
                </CardHeader>
                <div className="grid grid-cols-3 gap-4 mt-4">
                  <div className="p-4 border border-outline-variant rounded-xl bg-surface-container">
                    <h4 className="text-[12px] font-bold uppercase tracking-wider text-on-surface-variant mb-1">Ideas Logged</h4>
                    <span className="text-3xl font-display font-bold text-on-surface">{ideaCount}</span>
                  </div>
                  <div className="p-4 border border-outline-variant rounded-xl bg-surface-container">
                    <h4 className="text-[12px] font-bold uppercase tracking-wider text-on-surface-variant mb-1">Drafting</h4>
                    <span className="text-3xl font-display font-bold text-on-surface">{draftCount}</span>
                  </div>
                  <div className="p-4 border-2 border-warning/50 rounded-xl bg-surface relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-1 h-full bg-warning" />
                    <h4 className="text-[12px] font-bold uppercase tracking-wider text-warning mb-1">Requires Approval</h4>
                    <span className="text-3xl font-display font-bold text-on-surface">{reviewCount}</span>
                  </div>
                </div>
              </Card>

              {/* Data Table abstraction */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <CardTitle>Active Pipeline</CardTitle>
                    <Button variant="secondary" size="sm">New Idea</Button>
                  </div>
                </CardHeader>
                <div className="flex flex-col gap-2 mt-4">
                  {localData.ideas.map(idea => (
                    <div key={idea.id} className="flex items-center justify-between p-3.5 border border-outline-variant rounded-xl bg-surface hover:border-primary/30 transition-colors cursor-pointer" onClick={() => { setActiveIdeaId(idea.id); setActiveTab("script_builder"); }}>
                      <div className="flex items-center gap-4">
                        <Badge variant={getStageColor(idea.stage)} size="sm">{idea.stage}</Badge>
                        <span className="text-[13.5px] font-semibold text-on-surface">{idea.title}</span>
                      </div>
                      <div>
                        {idea.status === "requires_review" && <Badge variant="warning" size="sm">Review Pending</Badge>}
                        {idea.status === "idea" && <Badge variant="neutral" size="sm">Idea</Badge>}
                        {idea.status === "drafting" && <Badge variant="primary" size="sm">Drafting AI</Badge>}
                      </div>
                    </div>
                  ))}
                </div>
              </Card>

            </div>

            {/* Side Panel */}
            <div className="space-y-6">
              <Card>
                <CardHeader>
                  <CardTitle>Market Anomalies</CardTitle>
                  <p className="text-[12px] text-on-surface-variant mt-1 leading-relaxed">
                    Detected signals requiring immediate brand reaction.
                  </p>
                </CardHeader>
                <div className="space-y-4 mt-4">
                  {localData.marketSignals.map(sig => (
                    <div key={sig.id} className="p-3 border border-primary/20 bg-[#F0FDF4] rounded-lg">
                      <div className="flex items-center justify-between mb-1.5">
                        <span className="text-[11px] font-bold text-primary uppercase tracking-wider">{sig.topic}</span>
                        <span className="text-[11px] font-medium text-on-surface-variant">{sig.source}</span>
                      </div>
                      <p className="text-[13px] text-on-surface font-medium leading-relaxed">{sig.signalText}</p>
                      <Button variant="ghost" size="sm" className="mt-2 w-full text-xs text-primary">Generate Strike Script</Button>
                    </div>
                  ))}
                </div>
              </Card>
            </div>

          </div>
        )}

        {/* OPPORTUNITIES (Market Intel Subtab) */}
        {activeTab === "opportunities" && (
           <Card>
             <CardHeader>
               <CardTitle>Market Intelligence Stream</CardTitle>
             </CardHeader>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                {localData.marketSignals.map(sig => (
                  <div key={sig.id} className="p-4 border border-outline-variant bg-surface rounded-xl flex flex-col justify-between">
                    <div>
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-[12px] font-bold text-on-surface uppercase tracking-wider">{sig.topic}</span>
                        <Badge variant="primary" size="sm">Signal</Badge>
                      </div>
                      <p className="text-[13.5px] text-on-surface-variant font-medium leading-relaxed">{sig.signalText}</p>
                    </div>
                    <div className="mt-4 pt-4 border-t border-outline-variant flex justify-between items-center">
                       <span className="text-[11px] text-outline font-semibold uppercase">{sig.source}</span>
                       <Button variant="secondary" size="sm">Target Submarket</Button>
                    </div>
                  </div>
                ))}
             </div>
           </Card>
        )}

        {/* SCRIPT BUILDER CANVAS */}
        {activeTab === "script_builder" && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 h-full">
            {/* Left Parameters */}
            <div className="lg:col-span-4 space-y-6">
               <Card className="h-full">
                 <CardHeader>
                   <CardTitle>Structural Parameters</CardTitle>
                   <p className="text-[12px] text-on-surface-variant mt-1 leading-snug">Define the input constraints securely against the corporate DNA.</p>
                 </CardHeader>

                 {!activeIdeaId ? (
                   <Alert variant="info" title="No Script Loaded" className="mt-4">
                     Please select an idea from the Workload Overview to load its structural configuration.
                   </Alert>
                 ) : activeIdea ? (
                   <div className="mt-4 space-y-5">
                      <FormField label="Working Title">
                        <Input value={activeIdea.title} onChange={(e) => handleIdeaFieldChange(activeIdea.id, "title", e.target.value)} />
                      </FormField>

                      <div className="grid grid-cols-2 gap-4">
                        <FormField label="Funnel Vector">
                          <Select value={activeIdea.stage} onChange={(e) => handleIdeaFieldChange(activeIdea.id, "stage", e.target.value as any)}>
                            <option value="TOF">Top of Funnel (Awareness)</option>
                            <option value="MOF">Mid Funnel (Trust)</option>
                            <option value="BOF">Bottom Funnel (Conversion)</option>
                          </Select>
                        </FormField>
                        <FormField label="Copy Framework">
                          <Select value={activeIdea.framework} onChange={(e) => handleIdeaFieldChange(activeIdea.id, "framework", e.target.value)}>
                            <option value="Contrarian Truth">Contrarian Truth</option>
                            <option value="Listicle">Listicle / Steps</option>
                            <option value="Hero's Journey">Hero's Journey</option>
                            <option value="AIDA">AIDA Standard</option>
                          </Select>
                        </FormField>
                      </div>

                      <FormField label="Psychological Angle">
                        <Textarea 
                          rows={2} 
                          value={activeIdea.angle || ""} 
                          onChange={(e) => handleIdeaFieldChange(activeIdea.id, "angle", e.target.value)}
                          placeholder="e.g. Target the fallacy that more volume equals more profit..."
                        />
                      </FormField>

                      <FormField label="Strategic Output Goal">
                        <Textarea 
                          rows={2} 
                          value={activeIdea.outputGoal || ""} 
                          onChange={(e) => handleIdeaFieldChange(activeIdea.id, "outputGoal", e.target.value)}
                          placeholder="What must happen when they finish reading?"
                        />
                      </FormField>

                      <div className="mt-6 pt-4 border-t border-outline-variant">
                         <Button 
                           variant="primary" 
                           onClick={() => handleAIBuildTrigger(activeIdea.id)} 
                           isLoading={isDrafting}
                           className="w-full"
                         >
                           {draftSuccess ? "Draft Generated" : "Command Asset Generation"}
                         </Button>
                      </div>
                   </div>
                 ) : null}
               </Card>
            </div>

            {/* Right Canvas */}
            <div className="lg:col-span-8 flex flex-col h-full bg-surface-container rounded-2xl border border-outline-variant overflow-hidden shadow-sm">
                {/* Header status bar */}
                <div className="h-14 border-b border-outline-variant bg-surface px-6 flex items-center justify-between sticky top-0 z-10">
                  <div className="flex items-center gap-3">
                     <span className="material-symbols-outlined text-[18px] text-outline">description</span>
                     <span className="font-display font-semibold text-[13.5px] text-on-surface">Asset Canvas</span>
                  </div>
                  {activeIdea && (
                    <div className="flex items-center gap-3">
                      {activeIdea.status === "requires_review" && <Badge variant="warning" size="sm">Human Review Required</Badge>}
                      <Button 
                        variant={activeIdea.status === "requires_review" ? "primary" : activeIdea.status === "approved" ? "secondary" : "outline"} 
                        size="sm" 
                        disabled={!activeIdea.contentDraft || activeIdea.status === "approved"}
                        isLoading={isApproving}
                        onClick={() => handleApprove(activeIdea.id)}
                      >
                        {activeIdea.status === "approved" ? "Asset Approved" : "Approve for Production"}
                      </Button>
                    </div>
                  )}
                </div>

                {/* Editor Surface */}
                <div className="p-8 flex-grow relative bg-surface">
                   {!activeIdeaId ? (
                     <div className="absolute inset-0 flex flex-col items-center justify-center text-center p-6">
                        <div className="w-16 h-16 rounded-full bg-surface-container flex items-center justify-center mb-4 border border-outline-variant">
                          <span className="material-symbols-outlined text-outline text-[24px]">edit_document</span>
                        </div>
                        <h4 className="font-display font-bold text-on-surface text-lg">No Active Canvas</h4>
                        <p className="text-[13px] text-on-surface-variant mt-1.5 max-w-sm">
                          Select an idea from the Workload Overview on the left to edit script configurations and view generated assets.
                        </p>
                     </div>
                   ) : (
                     <div className="h-full">
                       {isDrafting ? (
                         <div className="flex flex-col items-center justify-center h-[400px] animate-pulse">
                           <div className="w-8 h-8 border-4 border-primary/30 border-t-primary rounded-full animate-spin mb-4" />
                           <p className="text-[13px] font-bold text-on-surface-variant uppercase tracking-widest">Compiling against Foundation DNA...</p>
                         </div>
                       ) : activeIdea?.contentDraft ? (
                         <div className="max-w-[700px] mx-auto">
                            {activeIdea.status === "requires_review" && (
                              <div className="mb-4 bg-[#EFF6FF] border border-blue-200 text-blue-800 text-[12px] font-semibold p-2.5 rounded-lg flex items-start gap-2">
                                <span className="material-symbols-outlined text-[16px] mt-0.5">info</span>
                                <div>This asset was generated natively holding Founder Voice logic constraints. Manual edits required before final approval.</div>
                              </div>
                            )}
                            <textarea 
                              className="w-full h-[600px] resize-none outline-none text-[15px] leading-[1.8] text-on-surface bg-transparent font-medium"
                              value={activeIdea.contentDraft}
                              onChange={(e) => handleIdeaFieldChange(activeIdea.id, "contentDraft", e.target.value)}
                            />
                         </div>
                       ) : (
                         <div className="flex flex-col items-center justify-center h-[400px] text-center border-2 border-dashed border-outline-variant rounded-xl bg-surface/50">
                           <span className="material-symbols-outlined text-outline text-[32px] mb-3">auto_awesome</span>
                           <h4 className="font-display font-bold text-on-surface text-[15px]">Canvas Blank</h4>
                           <p className="text-[13px] text-on-surface-variant mt-1 max-w-[280px]">
                             Configure parameters strictly on the left and run Asset Generation to inject contextual DNA into an output format.
                           </p>
                         </div>
                       )}
                     </div>
                   )}
                </div>
            </div>

          </div>
        )}

      </div>
    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { useRouter } from "next/navigation";
import { 
  getCalendar, 
  updateCalendarEvent,
  completeCalendarEvent
} from "@/lib/adapters";
import { 
  CalendarData, 
  CalendarEvent,
  CalendarEventStatus,
  CalendarPriority
} from "@/lib/types";

import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Modal } from "@/components/ui/Modal";
import { Input, Select, FormField } from "@/components/ui/Forms";
import { Skeleton, CardSkeleton } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { ConfirmationDialog } from "@/components/ui/ConfirmationDialog";

function getPriorityBadgeVariant(priority: CalendarPriority) {
  switch (priority) {
    case "URGENT": return "danger";
    case "HIGH": return "warning";
    case "STANDARD":
    default: return "neutral";
  }
}

function getStatusBadgeVariant(status: CalendarEventStatus) {
  switch (status) {
    case "MISSED":
    case "CONFLICT": return "danger";
    case "COMPLETED": return "success";
    case "SCHEDULED":
    default: return "neutral";
  }
}

export default function CalendarWorkspace() {
  const router = useRouter();

  const [data, setData] = useState<CalendarData | null>(null);
  const [localData, setLocalData] = useState<CalendarData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [mutationError, setMutationError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Modal buffer state
  const [selectedEventId, setSelectedEventId] = useState<string | null>(null);
  const activeEvent = localData?.events.find(e => e.id === selectedEventId);

  // Edits
  const [isEditingEvent, setIsEditingEvent] = useState(false);
  const [eventDraft, setEventDraft] = useState<CalendarEvent | null>(null);

  // Confidence boundaries
  const [confirmCompleteAction, setConfirmCompleteAction] = useState<{ id: string, title: string } | null>(null);

  const loadData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await getCalendar();
      setData(res);
      setLocalData(res);
    } catch (err: unknown) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // --------------- MUTATION WORKFLOW ---------------
  function handleEditEvent() {
    if (!activeEvent) return;
    setMutationError(null);
    setEventDraft({ ...activeEvent });
    setIsEditingEvent(true);
  }

  function handleCancelEdit() {
    setMutationError(null);
    setEventDraft(null);
    setIsEditingEvent(false);
  }

  async function handleSaveEvent() {
    if (!eventDraft) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateCalendarEvent(eventDraft);
      setLocalData(res);
      setData(res);
      setIsEditingEvent(false);
      setEventDraft(null);
    } catch (err: unknown) {
      setMutationError("Failed to update event: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  async function executeCompletion() {
    if (!confirmCompleteAction || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await completeCalendarEvent(confirmCompleteAction.id);
      setLocalData(res);
      setData(res);
      setConfirmCompleteAction(null);
    } catch(err: unknown) {
      setMutationError("Completion routing failed: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- RENDER STATES ---------------
  if (loading) {
    return (
      <div className="max-w-[1400px] mx-auto p-6 md:p-8 animate-in fade-in duration-500 space-y-8">
        <header className="mb-6">
          <Skeleton className="h-8 w-48 mb-2" />
          <Skeleton className="h-4 w-64" />
        </header>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  if (error || !localData) {
    return (
      <div className="max-w-[800px] mx-auto mt-12">
        <Alert variant="danger" title="Calendar Sync Error">
          {error}
          <div className="mt-4">
            <Button variant="secondary" onClick={loadData}>Retry Connection</Button>
          </div>
        </Alert>
      </div>
    );
  }

  // Slice categories
  const attentionRequired = localData.events.filter(e => e.status === "CONFLICT" || e.status === "MISSED");
  const upcomingEvents = localData.events.filter(e => e.status === "SCHEDULED");
  const completedEvents = localData.events.filter(e => e.status === "COMPLETED");

  const RenderCard = ({ event }: { event: CalendarEvent }) => (
    <Card 
      className={`cursor-pointer transition-shadow hover:shadow-md flex flex-col h-full 
        ${event.status === 'CONFLICT' || event.status === 'MISSED' ? 'border-error/30 ring-1 ring-error/20 bg-error/5' : 'bg-surface'}
      `}
      onClick={() => setSelectedEventId(event.id)}
    >
      <div className="p-5 flex flex-col h-full">
        <div className="flex justify-between items-start mb-3">
          <div className="flex items-center gap-2">
            <Badge variant={getStatusBadgeVariant(event.status)} size="sm">{event.status}</Badge>
            <Badge variant={getPriorityBadgeVariant(event.priority)} size="sm">{event.priority}</Badge>
          </div>
          {event.sourceModule && (
            <span className="text-[11px] font-bold text-on-surface-variant uppercase border border-outline-variant px-1 rounded-sm">
              {event.sourceModule}
            </span>
          )}
        </div>
        <h3 className="text-[16px] font-bold text-on-surface mb-1">{event.title}</h3>
        <p className="text-[13px] text-on-surface-variant mb-4 flex-1 line-clamp-3">{event.description}</p>

        {event.intelligenceSignal && (
          <div className="mb-4 bg-primary/10 text-[12px] font-medium text-primary-dark p-2.5 rounded-md flex items-start gap-1.5 border border-primary/20">
            <span className="material-symbols-outlined text-[15px] mt-0.5">warning</span>
            <span className="leading-tight">{event.intelligenceSignal}</span>
          </div>
        )}

        <div className="pt-4 border-t border-outline-variant">
           <div className="flex items-center justify-between text-[12.5px] font-medium text-on-surface">
              <span className="flex items-center gap-1.5">
                <span className="material-symbols-outlined text-[15px]">event</span> 
                {new Date(event.date).toLocaleDateString()}
              </span>
              <span className="text-on-surface-variant">{event.startTime} - {event.endTime}</span>
           </div>

           <div className="mt-2.5 flex items-center gap-1.5 text-[12px] font-medium text-on-surface-variant">
             <span className="material-symbols-outlined text-[14px]">person</span> 
             {event.owner}
           </div>
        </div>
      </div>
    </Card>
  );

  return (
    <div className="max-w-[1400px] mx-auto p-6 md:p-8 space-y-10 animate-in fade-in duration-500">

      {/* -------------------- HEADER -------------------- */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-outline-variant pb-6">
        <div>
          <h1 className="text-[28px] font-display font-medium text-on-surface tracking-tight">Calendar</h1>
          <p className="text-on-surface-variant text-[15px] mt-1">Operational schedule resolving conflicts and commitments.</p>
        </div>
        <div className="flex bg-surface border border-outline-variant rounded-[var(--radius-lg)] p-1.5 text-center shadow-sm">
           <div className="px-5 py-2 border-r border-outline-variant uppercase">
             <span className="block text-[11px] font-bold text-error tracking-wider mb-0.5">Issues</span>
             <span className="text-[18px] font-display font-bold text-on-surface">{attentionRequired.length}</span>
           </div>
           <div className="px-5 py-2 uppercase">
             <span className="block text-[11px] font-bold text-on-surface-variant tracking-wider mb-0.5">Scheduled</span>
             <span className="text-[18px] font-display font-bold text-on-surface">{upcomingEvents.length}</span>
           </div>
        </div>
      </header>

      {/* -------------------- ATTENTION REQUIRED -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-error text-[20px]">report</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">Attention Required</h2>
        </div>
        {attentionRequired.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
             {attentionRequired.map(event => <RenderCard key={event.id} event={event} />)}
          </div>
        ) : (
          <div className="text-center p-8 bg-surface-container rounded-xl border border-outline-variant text-on-surface-variant flex flex-col items-center">
            <span className="material-symbols-outlined text-[32px] mb-2 text-success">event_available</span>
            <p className="font-semibold text-on-surface text-[14.5px] mb-1">Clear Schedule</p>
            <p className="text-[13px]">No calendar conflicts or missed meetings.</p>
          </div>
        )}
      </section>

      {/* -------------------- UPCOMING -------------------- */}
      <section>
         <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-on-surface-variant text-[20px]">calendar_today</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">Upcoming</h2>
         </div>
         {upcomingEvents.length > 0 ? (
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
             {upcomingEvents.map(event => <RenderCard key={event.id} event={event} />)}
           </div>
         ) : (
           <div className="text-center p-8 bg-surface-container rounded-xl border border-outline-variant text-on-surface-variant">
             <p className="text-[13px]">No upcoming commitments scheduled.</p>
           </div>
         )}
      </section>

      {/* -------------------- RECENTLY COMPLETED -------------------- */}
      <section>
         <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant mb-4">Recently Completed</h2>
         {completedEvents.length > 0 ? (
           <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
             {completedEvents.map(event => (
                <div key={event.id} onClick={() => setSelectedEventId(event.id)} className="cursor-pointer bg-surface-container border border-outline-variant rounded-lg p-3.5 flex justify-between items-center transition-colors hover:bg-surface-container-high">
                  <div className="flex-1 pr-3">
                    <h5 className="font-bold text-[13.5px] text-on-surface mb-0.5 line-clamp-1">{event.title}</h5>
                    <p className="text-[12px] text-on-surface-variant truncate">{event.date.split("T")[0]} {event.startTime}</p>
                  </div>
                  <div className="shrink-0">
                    <Badge variant="success" size="sm">DONE</Badge>
                  </div>
                </div>
             ))}
           </div>
         ) : (
           <div className="text-center p-6 bg-surface-container rounded-lg border border-outline-variant text-on-surface-variant text-[13px]">
             No recently completed meetings.
           </div>
         )}
      </section>

      {/* -------------------- DETAIL MODAL -------------------- */}
      <Modal isOpen={!!selectedEventId} onClose={() => { setSelectedEventId(null); setIsEditingEvent(false); }} title="Commitment Interface" size="lg">
         {activeEvent ? (
           <div className="flex flex-col gap-6 pb-4">

              {mutationError && (
                 <Alert variant="danger" title="Action Failed">
                   {mutationError}
                   <div className="mt-3">
                     <Button variant="secondary" size="sm" onClick={() => setMutationError(null)}>Dismiss</Button>
                   </div>
                 </Alert>
              )}

              {/* Header Identification */}
              <div className="flex flex-col md:flex-row justify-between items-start border-b border-outline-variant pb-5">
                 <div className="flex-1 pr-4">
                   {activeEvent.sourceModule && (
                     <div className="flex items-center gap-2 mb-2">
                       <span className="text-[11px] font-bold text-primary tracking-wider uppercase border text-primary border-primary/30 bg-primary/10 px-2 py-0.5 rounded-sm">
                         MODULE: {activeEvent.sourceModule}
                       </span>
                     </div>
                   )}
                   <h2 className="text-[24px] font-display font-bold text-on-surface leading-tight">{activeEvent.title}</h2>
                   <p className="text-[15px] text-on-surface-variant mt-2 leading-relaxed">{activeEvent.description}</p>
                 </div>
                 <div className="flex flex-row md:flex-col gap-2 mt-4 md:mt-0 text-right shrink-0">
                    <Badge variant={getStatusBadgeVariant(activeEvent.status)}>{activeEvent.status}</Badge>
                    <Badge variant={getPriorityBadgeVariant(activeEvent.priority)}>{activeEvent.priority} PRIORITY</Badge>
                 </div>
              </div>

              {/* Intelligence / Context Banners */}
              <div className="space-y-3">
                {activeEvent.intelligenceSignal && (
                  <div className="bg-primary/5 text-[14px] font-medium text-primary-dark px-4 py-3 rounded-lg flex items-start gap-2 border border-primary/20">
                      <span className="material-symbols-outlined mt-0.5">insights</span>
                      <span className="leading-relaxed"><strong className="text-primary mr-1">Signal:</strong> {activeEvent.intelligenceSignal}</span>
                  </div>
                )}
                {activeEvent.linkedContext && (
                  <div className="bg-surface-container-low text-[13px] text-on-surface font-medium px-4 py-2.5 rounded-lg flex items-center gap-2 border border-outline-variant">
                      <span className="material-symbols-outlined text-[15px]">link</span>
                      <span>Entity Context: {activeEvent.linkedContext}</span>
                  </div>
                )}
              </div>

              {/* Read / Edit Boundary */}
              <section className="bg-surface border border-outline-variant rounded-xl p-5 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                   <h3 className="font-bold text-[15px] uppercase tracking-wider flex items-center gap-2 text-on-surface-variant">
                     <span className="material-symbols-outlined text-[18px]">event_note</span> Schedule Parameters
                   </h3>
                   {!isEditingEvent ? (
                     <Button variant="secondary" size="sm" onClick={handleEditEvent}>Edit Properties</Button>
                   ) : (
                     <div className="flex gap-2">
                       <Button variant="secondary" size="sm" onClick={handleCancelEdit} disabled={isSaving}>Cancel</Button>
                       <Button variant="primary" size="sm" onClick={handleSaveEvent} isLoading={isSaving}>Save Edits</Button>
                     </div>
                   )}
                </div>

                {!isEditingEvent ? (
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-[13px]">
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Date</span>
                       <span className="font-medium text-on-surface">{new Date(activeEvent.date).toLocaleDateString()}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Time</span>
                       <span className="font-medium text-on-surface">{activeEvent.startTime} - {activeEvent.endTime}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Owner</span>
                       <span className="font-medium text-on-surface line-clamp-1">{activeEvent.owner}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Status</span>
                       <span className="font-medium text-on-surface">{activeEvent.status}</span>
                     </div>
                   </div>
                ) : (
                   <div className="space-y-4">
                      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <FormField label="Date (YYYY-MM-DD)">
                           <Input 
                            value={eventDraft?.date ? new Date(eventDraft.date).toISOString().split('T')[0] : ""}
                            type="date"
                            onChange={(e) => setEventDraft(prev => prev ? {...prev, date: new Date(e.target.value).toISOString()} : null)}
                           />
                        </FormField>
                        <FormField label="Start Time">
                           <Input 
                            value={eventDraft?.startTime || ""} 
                            onChange={(e) => setEventDraft(prev => prev ? {...prev, startTime: e.target.value} : null)}
                           />
                        </FormField>
                        <FormField label="End Time">
                           <Input 
                            value={eventDraft?.endTime || ""} 
                            onChange={(e) => setEventDraft(prev => prev ? {...prev, endTime: e.target.value} : null)}
                           />
                        </FormField>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="Status">
                          <Select
                            value={eventDraft?.status || "SCHEDULED"}
                            onChange={(e) => setEventDraft(prev => prev ? {...prev, status: e.target.value as CalendarEventStatus} : null)}
                          >
                            <option value="SCHEDULED">SCHEDULED</option>
                            <option value="MISSED">MISSED</option>
                            <option value="CONFLICT">CONFLICT</option>
                            <option value="COMPLETED">COMPLETED</option>
                          </Select>
                        </FormField>
                        <FormField label="Priority">
                          <Select
                            value={eventDraft?.priority || "STANDARD"}
                            onChange={(e) => setEventDraft(prev => prev ? {...prev, priority: e.target.value as CalendarPriority} : null)}
                          >
                            <option value="STANDARD">STANDARD</option>
                            <option value="HIGH">HIGH</option>
                            <option value="URGENT">URGENT</option>
                          </Select>
                        </FormField>
                      </div>
                   </div>
                )}
              </section>

              {/* Action / Next Steps Region */}
              <section className="bg-surface-container border border-outline-variant rounded-xl p-5 flex flex-col md:flex-row justify-between items-start md:items-center gap-5">
                 <div className="flex-1">
                    <h4 className="text-[12px] font-bold uppercase tracking-wider text-on-surface-variant mb-1">Expected Next Action</h4>
                    <p className="text-[14.5px] font-medium text-on-surface">{activeEvent.recommendedAction || "Ensure attendance or manually reschedule."}</p>
                 </div>

                 <div className="flex flex-col gap-2 shrink-0 w-full md:w-auto">
                    {activeEvent.sourceModule && (
                      <Button 
                         variant="primary" 
                         className="w-full justify-center"
                         onClick={() => {
                            const dest = activeEvent.sourceModule?.toLowerCase();
                            if (dest) router.push(`/${dest}`);
                         }}
                      >
                         View Source Context
                      </Button>
                    )}

                    {activeEvent.status !== "COMPLETED" && (
                       <Button 
                          variant="secondary" 
                          className="w-full justify-center" 
                          onClick={() => setConfirmCompleteAction({ id: activeEvent.id, title: activeEvent.title })}
                       >
                          Log as Completed
                       </Button>
                    )}
                 </div>
              </section>

           </div>
         ) : <Skeleton className="h-64 w-full" />}
      </Modal>

      <ConfirmationDialog
        isOpen={!!confirmCompleteAction}
        onClose={() => { if (!isSaving) setConfirmCompleteAction(null); }}
        onConfirm={executeCompletion}
        title="Complete Calendar Commitment"
        description={`Are you sure you want to mark "${confirmCompleteAction?.title}" as logged and completed?`}
        confirmText="Log Completed"
        isDestructive={false}
        isLoading={isSaving}
      />

    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { getConversion, updateOpportunity, updateFollowUp, updateQualification } from "@/lib/adapters";
import { ConversionData, Opportunity, FollowUp, OpportunityStage, Qualification } from "@/lib/types";

import { Card, CardTitle, CardHeader } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { FormField, Input, Select, Textarea } from "@/components/ui/Forms";
import { Badge } from "@/components/ui/Badge";
import { Skeleton, CardSkeleton } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { Tabs } from "@/components/ui/Tabs";
import { Modal } from "@/components/ui/Modal";

const STAGES: { value: OpportunityStage; label: string }[] = [
  { value: "QUALIFIED", label: "Qualified" },
  { value: "CALL_SCHEDULED", label: "Call Scheduled" },
  { value: "CALL_COMPLETED", label: "Call Completed" },
  { value: "PROPOSAL", label: "Proposal" },
  { value: "CLOSED_WON", label: "Closed Won" }
];

export default function ConversionPage() {
  const { data, setData, localData, setLocalData, loading, error, reload: loadData } = useAdapter(getConversion);

  const [activeTab, setActiveTab] = useState("pipeline");
  const [selectedOppId, setSelectedOppId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [mutationError, setMutationError] = useState<string | null>(null);
  const [isEditingQual, setIsEditingQual] = useState(false);
  const [qualDraft, setQualDraft] = useState<Qualification | null>(null);

  const activeOpp = localData?.opportunities.find(o => o.id === selectedOppId);

  // Mutations
  async function handleStageChange(newStage: OpportunityStage) {
    if (!activeOpp || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const updatedOpp = { ...activeOpp, stage: newStage };
      const res = await updateOpportunity(updatedOpp);
      setLocalData(res);
      setData(res);
    } catch (err: unknown) {
      setMutationError("Failed to change stage: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  async function handleFollowUpComplete(followUp: FollowUp) {
    setMutationError(null);
    setIsSaving(true);
    try {
      const updated = { ...followUp, status: "COMPLETED" as const };
      const res = await updateFollowUp(updated);
      setLocalData(res);
      setData(res);
    } catch (err: unknown) {
      setMutationError("Failed to update follow-up: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  async function handleQualificationSave() {
    if (!activeOpp || !localData || !qualDraft) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateQualification(activeOpp.id, qualDraft);
      setLocalData(res);
      setData(res);
      setIsEditingQual(false);
    } catch (err: unknown) {
      setMutationError("Failed to save qualification: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  function handleQualEditStart() {
    if (!activeOpp) return;
    setMutationError(null);
    setQualDraft({ ...activeOpp.qualification });
    setIsEditingQual(true);
  }

  function handleQualEditCancel() {
    setMutationError(null);
    setQualDraft(null);
    setIsEditingQual(false);
  }

  if (loading) {
    return (
      <div className="p-6 md:p-8 lg:p-12 max-w-[1400px] mx-auto animate-in fade-in duration-300">
        <Skeleton className="h-8 w-64 mb-2" />
        <Skeleton className="h-4 w-48 mb-8" />
        <CardSkeleton />
      </div>
    );
  }

  if (error || !data || !localData) {
    return (
      <div className="p-6 md:p-8 lg:p-12 max-w-[1400px] mx-auto">
        <Alert variant="danger" title="Conversion Offline">
          {error || "Unable to load Conversion data."}
          <div className="mt-4">
            <Button variant="secondary" size="sm" onClick={loadData}>Restart Engine</Button>
          </div>
        </Alert>
      </div>
    );
  }

  // Derived View Helpers
  const openFollowUps = localData.followUps.filter(f => f.status !== "COMPLETED");
  const staleOpps = localData.opportunities.filter(o => o.daysInactive >= 5);

  return (
    <div className="p-6 md:p-8 lg:p-12 max-w-[1400px] mx-auto">

      {/* HEADER & INTELLIGENCE */}
      <header className="mb-8">
        <div className="flex flex-col md:flex-row md:items-start justify-between gap-6">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <h1 className="text-3xl lg:text-[40px] font-display font-bold text-on-surface tracking-tight uppercase">
                Conversion
              </h1>
              <Badge variant="primary" size="sm">Pipeline Architecture</Badge>
            </div>
            <p className="text-on-surface-variant text-[14.5px] font-medium max-w-2xl leading-relaxed">
              Transform mapped attention securely into active financial progress. Control stages intimately scaling predictability across the workflow matrix.
            </p>
          </div>
          <div className="flex gap-4">
            <Card variant="outlined" className="min-w-[180px] p-4 flex flex-col justify-between">
               <h3 className="font-display font-medium text-[11px] text-on-surface-variant uppercase tracking-widest mb-1">Pipeline Value</h3>
               <div className="text-2xl font-bold font-display">${localData.pipelineValue.toLocaleString()}</div>
            </Card>
          </div>
        </div>

        {staleOpps.length > 0 && (
          <Alert variant="warning" title="Primary Conversion Constraint" className="mt-6 border-l-4 border-l-warning">
            {staleOpps.length} qualified opportunit{staleOpps.length === 1 ? 'y has' : 'ies have'} had no activity in 5+ days. Review actively to avoid pipeline hemorrhage.
            <div className="mt-3">
              <Button variant="secondary" size="sm" onClick={() => setActiveTab("followups")}>Review Follow-Ups</Button>
            </div>
          </Alert>
        )}
      </header>

      {/* TABS */}
      <div className="mb-6 border-b border-outline-variant">
        <Tabs 
          tabs={[
            { id: "pipeline", label: "Pipeline" },
            { id: "leads", label: "Leads Workspace" },
            { id: "followups", label: `Follow-Ups (${openFollowUps.length})` }
          ]} 
          activeTab={activeTab} 
          onChange={setActiveTab} 
        />
      </div>

      {/* PIPELINE KANBAN */}
      {activeTab === "pipeline" && (
        <div className="flex gap-4 overflow-x-auto pb-4 snap-x">
          {STAGES.map(stage => {
            const oppsInStage = localData.opportunities.filter(o => o.stage === stage.value);
            return (
              <div key={stage.value} className="flex-none w-[320px] bg-surface-container/50 rounded-xl p-3 border border-outline-variant snap-start">
                <div className="flex items-center justify-between mb-4 px-1">
                  <h3 className="font-display font-semibold text-[13px] uppercase tracking-wider text-on-surface">{stage.label}</h3>
                  <Badge variant="neutral" size="sm">{oppsInStage.length}</Badge>
                </div>
                <div className="flex flex-col gap-3 min-h-[150px]">
                  {oppsInStage.length === 0 ? (
                    <div className="text-[12px] text-on-surface-variant/70 text-center py-6 font-medium italic">Empty Stage</div>
                  ) : (
                    oppsInStage.map(opp => (
                      <Card 
                        key={opp.id} 
                        className="cursor-pointer hover:border-primary/40 transition-colors shadow-sm"
                        onClick={() => setSelectedOppId(opp.id)}
                      >
                        <div className="p-4">
                          <div className="flex items-start justify-between mb-2">
                             <Badge variant={opp.priority === "high" || opp.priority === "critical" ? "warning" : "neutral"} size="sm">
                               {opp.priority}
                             </Badge>
                             <span className="text-[12px] font-bold text-on-surface-variant">${opp.value.toLocaleString()}</span>
                          </div>
                          <h4 className="font-semibold text-[14.5px] text-on-surface mb-1">{opp.leadName}</h4>
                          <p className="text-[12px] font-medium text-on-surface-variant mb-4">{opp.company} &mdash; {opp.title}</p>

                          <div className="text-[11px] font-semibold text-primary uppercase border-t border-outline-variant pt-3">
                             {opp.nextAction}
                          </div>
                        </div>
                      </Card>
                    ))
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}

      {/* LEADS WORKSPACE */}
      {activeTab === "leads" && (
        <Card>
          <CardHeader>
            <CardTitle>Active Opportunities</CardTitle>
          </CardHeader>
          <div className="mt-4 flex flex-col gap-2">
             {localData.opportunities.map(opp => (
               <div key={opp.id} onClick={() => setSelectedOppId(opp.id)} className="p-4 border border-outline-variant bg-surface rounded-xl hover:border-primary/40 cursor-pointer flex flex-col md:flex-row md:items-center justify-between gap-4">
                 <div>
                   <div className="flex items-center gap-3 mb-1">
                     <span className="font-bold text-[14.5px]">{opp.leadName}</span>
                     <Badge variant="neutral" size="sm">{opp.stage.replace("_", " ")}</Badge>
                   </div>
                   <div className="text-[13px] text-on-surface-variant font-medium">{opp.company} &mdash; {opp.title}</div>
                 </div>
                 <div className="text-right">
                   <div className="text-[12px] font-bold text-outline uppercase tracking-wider mb-1">Next Action</div>
                   <div className="text-[13px] font-semibold text-primary">{opp.nextAction}</div>
                 </div>
               </div>
             ))}
          </div>
        </Card>
      )}

      {/* FOLLOW-UPS */}
      {activeTab === "followups" && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {openFollowUps.length === 0 ? (
            <div className="col-span-full">
              <Alert variant="success" title="Clear">No follow-ups require attention currently.</Alert>
            </div>
          ) : (
            openFollowUps.map(fu => {
              const opp = localData.opportunities.find(o => o.id === fu.opportunityId);
              return (
                <Card key={fu.id} className="border-l-4 border-l-warning">
                  <div className="p-5">
                    <div className="flex items-center justify-between mb-3">
                      <Badge variant="warning" size="sm">{fu.status}</Badge>
                      <span className="text-[12px] font-bold text-on-surface-variant block">Due: {new Date(fu.dueDate).toLocaleDateString()}</span>
                    </div>
                    <h4 className="font-bold text-[15px] mb-2">{opp?.leadName || "Unknown Target"}</h4>
                    <p className="text-[13px] leading-relaxed text-on-surface-variant font-medium mb-4">{fu.reason}</p>
                    {fu.recommendedAction && (
                      <div className="bg-[#EFF6FF] border border-blue-200 text-blue-800 p-3 rounded-lg text-[13px] font-medium mb-4 flex gap-2 items-start">
                        <span className="material-symbols-outlined text-[16px] mt-0.5">auto_awesome</span>
                        <div>{fu.recommendedAction}</div>
                      </div>
                    )}
                    <Button 
                      variant="primary" 
                      size="sm" 
                      className="w-full"
                      isLoading={isSaving}
                      onClick={() => handleFollowUpComplete(fu)}
                    >
                      Mark Completed
                    </Button>
                  </div>
                </Card>
              )
            })
          )}
        </div>
      )}

      {/* CLOSER ROOM (Modal) */}
      <Modal isOpen={!!selectedOppId} onClose={() => setSelectedOppId(null)} title="Closer Room" size="lg">
         {activeOpp ? (
           <div className="flex flex-col gap-8 pb-4">
             {mutationError && (
               <Alert variant="danger" title="Mutation Failure">
                 {mutationError}
                 <div className="mt-3">
                   <Button variant="secondary" size="sm" onClick={() => setMutationError(null)}>Dismiss</Button>
                 </div>
               </Alert>
             )}

             {/* Header */}
             <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 bg-surface-container/50 border border-outline-variant p-5 rounded-xl">
               <div>
                 <h2 className="text-2xl font-display font-bold text-on-surface mb-1">{activeOpp.leadName}</h2>
                 <div className="text-[14px] text-on-surface-variant font-medium">{activeOpp.company} &mdash; ${activeOpp.value.toLocaleString()}</div>
               </div>
               <div className="flex items-center gap-3">
                 <div className="text-[11px] uppercase tracking-wider font-bold text-outline mr-2 text-right">
                   Current State
                   <div className="text-[13px] text-on-surface">{activeOpp.stage.replace("_", " ")}</div>
                 </div>
                 <div className="flex flex-col gap-2">
                   <select 
                     className="bg-surface border border-outline-variant rounded-md px-3 py-1.5 text-[13px] font-bold text-primary outline-none cursor-pointer"
                     value={activeOpp.stage}
                     onChange={(e) => handleStageChange(e.target.value as OpportunityStage)}
                     disabled={isSaving}
                   >
                     {STAGES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
                   </select>
                 </div>
               </div>
             </div>

             {activeOpp.stage === "CLOSED_WON" && (
                <Alert variant="success" title="CLOSED WON">
                  Target secured. Delivery handoff ready. Transition workflow into the Delivery architecture pipeline functionally.
                </Alert>
             )}

             {/* Dynamic Content Columns */}
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

               {/* Left Column: Qualification & Objections */}
               <div className="space-y-8">
                  <section>
                    <div className="border-b border-outline-variant pb-2 mb-4 flex items-center justify-between">
                      <h3 className="font-display font-bold text-[15px] uppercase tracking-wider flex items-center gap-2">
                        <span className="material-symbols-outlined text-[18px]">verified_user</span>
                        Qualification Context
                      </h3>
                      {!isEditingQual ? (
                        <Button variant="secondary" size="sm" onClick={handleQualEditStart}>Edit</Button>
                      ) : (
                        <div className="flex gap-2">
                          <Button variant="secondary" size="sm" onClick={handleQualEditCancel} disabled={isSaving}>Cancel</Button>
                          <Button variant="primary" size="sm" onClick={handleQualificationSave} isLoading={isSaving}>Save</Button>
                        </div>
                      )}
                    </div>

                    {!isEditingQual ? (
                      <div className="space-y-4 text-[13.5px]">
                        <div>
                          <strong className="block text-on-surface-variant text-[11px] uppercase mb-1">Problem Validated</strong>
                          <div className="font-medium">{activeOpp.qualification.problem}</div>
                        </div>
                        <div>
                          <strong className="block text-on-surface-variant text-[11px] uppercase mb-1">Fit</strong>
                          <div className="font-medium">{activeOpp.qualification.fit}</div>
                        </div>
                        <div>
                          <strong className="block text-on-surface-variant text-[11px] uppercase mb-1">Urgency / Timeline</strong>
                          <div className="font-medium">{activeOpp.qualification.urgency}</div>
                        </div>
                        <div>
                          <strong className="block text-on-surface-variant text-[11px] uppercase mb-1">Authority</strong>
                          <div className="font-medium">{activeOpp.qualification.authority}</div>
                        </div>
                        <div>
                          <strong className="block text-on-surface-variant text-[11px] uppercase mb-1">Budget</strong>
                          <div className="font-medium">{activeOpp.qualification.budget}</div>
                        </div>
                      </div>
                    ) : (
                      <div className="space-y-4 text-[13.5px]">
                        <FormField label="Problem Validated">
                           <Input 
                             value={qualDraft?.problem || ""} 
                             onChange={(e) => setQualDraft(prev => prev ? { ...prev, problem: e.target.value } : null)}
                           />
                        </FormField>
                        <FormField label="Fit">
                           <Input 
                             value={qualDraft?.fit || ""} 
                             onChange={(e) => setQualDraft(prev => prev ? { ...prev, fit: e.target.value } : null)}
                           />
                        </FormField>
                        <FormField label="Urgency / Timeline">
                           <Input 
                             value={qualDraft?.urgency || ""} 
                             onChange={(e) => setQualDraft(prev => prev ? { ...prev, urgency: e.target.value } : null)}
                           />
                        </FormField>
                        <FormField label="Authority">
                           <Input 
                             value={qualDraft?.authority || ""} 
                             onChange={(e) => setQualDraft(prev => prev ? { ...prev, authority: e.target.value } : null)}
                           />
                        </FormField>
                        <FormField label="Budget">
                           <Input 
                             value={qualDraft?.budget || ""} 
                             onChange={(e) => setQualDraft(prev => prev ? { ...prev, budget: e.target.value } : null)}
                           />
                        </FormField>
                      </div>
                    )}
                  </section>

                  <section>
                    <h3 className="font-display font-bold text-[15px] uppercase tracking-wider border-b border-outline-variant pb-2 mb-4 flex items-center gap-2">
                      <span className="material-symbols-outlined text-[18px]">warning</span>
                      Active Objections
                    </h3>
                    {activeOpp.objections.length === 0 ? (
                      <div className="text-[13px] italic text-on-surface-variant">No objections logged.</div>
                    ) : (
                      <div className="space-y-4">
                        {activeOpp.objections.map(obj => (
                          <div key={obj.id} className="p-3 border border-error/20 bg-error-container/30 rounded-lg">
                             <div className="flex items-center justify-between mb-2">
                               <Badge variant={obj.resolutionStatus === "resolved" ? "success" : "danger"} size="sm">{obj.category}</Badge>
                               <span className="text-[11px] font-bold uppercase">{obj.resolutionStatus}</span>
                             </div>
                             <p className="text-[13px] font-medium leading-relaxed mb-3">{obj.objectionText}</p>
                             {obj.responseGuidance && (
                               <div className="bg-surface p-2.5 rounded border border-outline-variant text-[12.5px] font-medium text-primary">
                                 <strong className="block text-[10px] uppercase tracking-wider mb-1 text-on-surface-variant">Intelligence Suggestion</strong>
                                 {obj.responseGuidance}
                               </div>
                             )}
                          </div>
                        ))}
                      </div>
                    )}
                  </section>
               </div>

               {/* Right Column: Interaction Log & Proposals */}
               <div className="space-y-8">
                  <section>
                    <h3 className="font-display font-bold text-[15px] uppercase tracking-wider border-b border-outline-variant pb-2 mb-4 flex items-center gap-2">
                      <span className="material-symbols-outlined text-[18px]">call</span>
                      Sales Execution
                    </h3>
                    <div className="bg-surface-container rounded-xl p-4 border border-outline-variant">
                      <div className="flex items-center justify-between mb-4">
                        <Badge variant={activeOpp.salesCall.status === "COMPLETED" ? "primary" : "neutral"} size="sm">
                          {activeOpp.salesCall.status.replace("_", " ")}
                        </Badge>
                        {activeOpp.salesCall.date && <span className="text-[12px] font-bold text-on-surface-variant">{new Date(activeOpp.salesCall.date).toLocaleDateString()}</span>}
                      </div>

                      {activeOpp.salesCall.outcome && (
                        <div className="mb-4">
                          <strong className="block text-[11px] uppercase text-on-surface-variant mb-1">Outcome</strong>
                          <p className="text-[13px] font-medium leading-relaxed">{activeOpp.salesCall.outcome}</p>
                        </div>
                      )}

                      {activeOpp.salesCall.notes && (
                         <div>
                          <strong className="block text-[11px] uppercase text-on-surface-variant mb-1">Log</strong>
                          <p className="text-[13px] font-medium leading-relaxed">{activeOpp.salesCall.notes}</p>
                        </div>
                      )}

                      {!activeOpp.salesCall.outcome && !activeOpp.salesCall.notes && (
                        <div className="text-[12px] italic text-on-surface-variant text-center py-2">No execution logged.</div>
                      )}
                    </div>
                  </section>

                  <section>
                    <h3 className="font-display font-bold text-[15px] uppercase tracking-wider border-b border-outline-variant pb-2 mb-4 flex items-center gap-2">
                      <span className="material-symbols-outlined text-[18px]">request_quote</span>
                      Proposal Canvas
                    </h3>

                    {activeOpp.proposal ? (
                      <div className="bg-surface border border-primary/20 rounded-xl p-4 shadow-sm">
                         <div className="flex justify-between items-center mb-3">
                           <Badge variant={activeOpp.proposal.status === "APPROVED" || activeOpp.proposal.status === "ACCEPTED" ? "success" : "warning"} size="sm">
                             {activeOpp.proposal.status}
                           </Badge>
                         </div>
                         <div className="space-y-3 text-[13px] font-medium">
                           <div>
                             <span className="block text-[11px] uppercase text-on-surface-variant font-bold mb-1">Offer Parameters</span>
                             {activeOpp.proposal.offerContext}
                           </div>
                           <div>
                             <span className="block text-[11px] uppercase text-on-surface-variant font-bold mb-1">Scope Constraints</span>
                             {activeOpp.proposal.scopeConstraints}
                           </div>
                         </div>
                      </div>
                    ) : (
                      <div className="bg-surface-container rounded-xl p-6 border border-outline-variant text-center">
                        <span className="material-symbols-outlined text-outline text-[32px] mb-2 block">assignment</span>
                        <div className="font-semibold text-on-surface text-[14.5px] mb-1">No Proposal Available</div>
                        <p className="text-[13px] text-on-surface-variant font-medium">Proposal preparation has not started.</p>
                      </div>
                    )}
                  </section>
               </div>

             </div>
           </div>
         ) : <Skeleton className="h-40 w-full" />}
      </Modal>

    </div>
  );
}

