                    icon={IconMap[action.type]}
                    badge={
                      <Badge variant={PriorityBadgeMap[action.priority]} size="sm">
                        {action.priority} priority
                      </Badge>
                    }
                    rightElement={
                      <Button variant="primary" size="sm" onClick={() => setPendingAction(action)}>
                        Resolve
                      </Button>
                    }
                  />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* 5. Context / Intelligence / Ecosystem Status */}
        <div className="flex flex-col gap-6">
          <Card variant="outlined">
            <CardHeader>
              <CardTitle>System Integrations</CardTitle>
            </CardHeader>
            <div className="flex flex-col gap-3">
              {Object.entries(data.automationStatus).map(([key, status]) => (
                <div key={key} className="flex items-center justify-between py-2 border-b border-outline-variant last:border-0">
                  <span className="text-[13px] text-on-surface capitalize font-medium">
                    {key.replace("_", " ")}
                  </span>
                  <Badge 
                    variant={status === "CONNECTED" || status === "SUCCESS" || status === "RUNNING" ? "success" : status === "NOT_CONFIGURED" ? "neutral" : "danger"} 
                    size="sm"
                  >
                    {status}
                  </Badge>
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>

      {/* Execution Confirmation */}
      <ConfirmationDialog
        isOpen={pendingAction !== null}
        onClose={() => setPendingAction(null)}
        onConfirm={handleExecuteAction}
        title={pendingAction?.title || "Confirm Action"}
        description={pendingAction?.subtitle || "Are you sure you want to execute this action? It may affect live business state."}
        confirmText="Confirm Execution"
        isLoading={isExecuting}
      />
    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { 
  getRetention, 
  updateRetentionEngagement, 
  addRetentionInteraction,
  updateRetentionRisk,
  updateRetentionAction
} from "@/lib/adapters";
import { 
  RetentionData, 
  RetentionEngagement, 
  RetentionStatus, 
  RetentionInteraction,
  RetentionRisk,
  RetentionNextAction
} from "@/lib/types";

import { Card, CardTitle, CardHeader } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Modal } from "@/components/ui/Modal";
import { Input, Textarea, Select, FormField } from "@/components/ui/Forms";
import { Skeleton, CardSkeleton, EmptyState } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { ConfirmationDialog } from "@/components/ui/ConfirmationDialog";

function getHealthBadgeProps(health: string) {
  switch (health) {
    case "HEALTHY": return { variant: "success" as const };
    case "WATCH": return { variant: "warning" as const };
    case "AT_RISK": return { variant: "danger" as const };
    default: return { variant: "neutral" as const };
  }
}

export default function RetentionWorkspace() {
  const [data, setData] = useState<RetentionData | null>(null);
  const [localData, setLocalData] = useState<RetentionData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [mutationError, setMutationError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Detail Modal Navigation
  const [selectedEngagementId, setSelectedEngagementId] = useState<string | null>(null);
  const activeEngagement = localData?.engagements.find(e => e.id === selectedEngagementId);

  // Edit Buffer: Engagement
  const [isEditingEngagement, setIsEditingEngagement] = useState(false);
  const [engagementDraft, setEngagementDraft] = useState<RetentionEngagement | null>(null);

  // Add Buffer: Interaction
  const [isAddingInteraction, setIsAddingInteraction] = useState(false);
  const [interactionDraft, setInteractionDraft] = useState<Partial<RetentionInteraction> | null>(null);

  // Confirmation actions
  const [confirmRiskResolve, setConfirmRiskResolve] = useState<{ engagementId: string, riskId: string } | null>(null);
  const [confirmActionComplete, setConfirmActionComplete] = useState<{ engagementId: string, actionId: string } | null>(null);

  async function loadData() {
    setLoading(true);
    setError(null);
    try {
      const res = await getRetention();
      setData(res);
      setLocalData(res);
    } catch (err: unknown) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  // --------------- ENGAGEMENT EDIT PIPELINE ---------------
  function handleEditEngagement() {
    if (!activeEngagement) return;
    setMutationError(null);
    setEngagementDraft({ ...activeEngagement });
    setIsEditingEngagement(true);
  }

  function handleCancelEdit() {
    setMutationError(null);
    setEngagementDraft(null);
    setIsEditingEngagement(false);
  }

  async function handleSaveEngagement() {
    if (!engagementDraft) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateRetentionEngagement(engagementDraft);
      setLocalData(res);
      setData(res);
      setIsEditingEngagement(false);
      setEngagementDraft(null);
    } catch (err: unknown) {
      setMutationError("Failed to save relationship details: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- INTERACTION PIPELINE ---------------
  function handleStartAddInteraction() {
    setMutationError(null);
    setInteractionDraft({
      type: "CHECK_IN",
      summary: "",
      owner: "ASENZO Ops"
    });
    setIsAddingInteraction(true);
  }

  function handleCancelAddInteraction() {
    setMutationError(null);
    setInteractionDraft(null);
    setIsAddingInteraction(false);
  }

  async function handleSaveInteraction() {
    if (!activeEngagement || !interactionDraft || !interactionDraft.summary) {
      setMutationError("Interaction summary is required.");
      return;
    }
    setMutationError(null);
    setIsSaving(true);
    try {
      const payload: RetentionInteraction = {
        id: `i${Date.now()}`,
        date: new Date().toISOString(),
        type: (interactionDraft.type || "OTHER") as RetentionInteraction["type"],
        summary: interactionDraft.summary,
        outcome: interactionDraft.outcome,
        owner: interactionDraft.owner || "System"
      };
      const res = await addRetentionInteraction(activeEngagement.id, payload);
      setLocalData(res);
      setData(res);
      setIsAddingInteraction(false);
      setInteractionDraft(null);
    } catch (err: unknown) {
      setMutationError("Failed to log interaction: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- RISK RESOLUTION PIPELINE ---------------
  async function executeRiskResolution() {
    if (!confirmRiskResolve || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      // Find the specific risk
      const engagement = localData.engagements.find(e => e.id === confirmRiskResolve.engagementId);
      const risk = engagement?.risks.find(r => r.id === confirmRiskResolve.riskId);
      if (!engagement || !risk) throw new Error("Risk not found.");

      const updatedRisk: RetentionRisk = { ...risk, status: "RESOLVED" };
      const res = await updateRetentionRisk(engagement.id, updatedRisk);
      setLocalData(res);
      setData(res);
      setConfirmRiskResolve(null);
    } catch(err: unknown) {
      setMutationError("Failed to resolve risk: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- ACTION COMPLETION PIPELINE ---------------
  async function executeActionCompletion() {
    if (!confirmActionComplete || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const engagement = localData.engagements.find(e => e.id === confirmActionComplete.engagementId);
      if (!engagement || !engagement.nextAction) throw new Error("Next action not found.");

      const updatedAction: RetentionNextAction = { ...engagement.nextAction, status: "COMPLETED" };
      const res = await updateRetentionAction(engagement.id, updatedAction);
      setLocalData(res);
      setData(res);
      setConfirmActionComplete(null);
    } catch(err: unknown) {
      setMutationError("Failed to complete next action: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // Rendering Loading
  if (loading) {
    return (
      <div className="max-w-[1400px] mx-auto p-6 md:p-8 animate-in fade-in duration-500 space-y-8">
        <header className="mb-6">
          <Skeleton className="h-8 w-48 mb-2" />
          <Skeleton className="h-4 w-64" />
        </header>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  // Rendering Error
  if (error || !localData) {
    return (
      <div className="max-w-[800px] mx-auto mt-12">
        <Alert variant="danger" title="Failed to load Retention Data">
          {error}
          <div className="mt-4">
            <Button variant="secondary" onClick={loadData}>Retry</Button>
          </div>
        </Alert>
      </div>
    );
  }

  // Data aggregations for operational displays
  const activeRelationships = localData.engagements.filter(e => e.status !== "COMPLETED");
  const needingAttention = localData.engagements.filter(e => e.health === "AT_RISK" || e.health === "WATCH" || e.status === "NEEDS_ATTENTION");
  const urgentRisks = localData.engagements.flatMap(e => e.risks.filter(r => r.status === "OPEN" && r.severity === "HIGH").map(r => ({ ...r, engagementClient: e.clientName, engagementId: e.id })));

  return (
    <div className="max-w-[1400px] mx-auto p-6 md:p-8 space-y-8 animate-in fade-in duration-500">

      {/* -------------------- HEADER / METRICS -------------------- */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-[28px] font-display font-medium text-on-surface tracking-tight">Customer Continuity</h1>
          <p className="text-on-surface-variant text-[15px] mt-1">Operational post-sale relationship and retention management.</p>
        </div>
        <div className="flex bg-surface-container-low border border-outline-variant rounded-[var(--radius-lg)] p-1">
          <div className="px-4 py-1.5 flex flex-col items-center border-r border-outline-variant last:border-0">
            <span className="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant">Active</span>
            <span className="text-[17px] font-display font-bold text-on-surface">{activeRelationships.length}</span>
          </div>
          <div className="px-4 py-1.5 flex flex-col items-center border-r border-outline-variant last:border-0">
            <span className="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant">Review</span>
            <span className="text-[17px] font-display font-bold text-warning">{needingAttention.length}</span>
          </div>
          <div className="px-4 py-1.5 flex flex-col items-center">
            <span className="text-[11px] font-bold uppercase tracking-wider text-on-surface-variant">Urgent</span>
            <span className="text-[17px] font-display font-bold text-error">{urgentRisks.length}</span>
          </div>
        </div>
      </header>

      {/* -------------------- PRIMARY ATTENTION AREA -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-3">
           <span className="material-symbols-outlined text-error text-[20px]">warning</span>
           <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant">Attention Required</h2>
        </div>

        {needingAttention.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {needingAttention.map(engagement => (
               <Card 
                key={`urgent-${engagement.id}`} 
                className={`cursor-pointer transition-shadow hover:shadow-md ${engagement.health === "AT_RISK" ? "border-error/40 ring-1 ring-error/20 bg-error/5" : "border-warning/40 ring-1 ring-warning/20 bg-warning/5"}`}
                onClick={() => setSelectedEngagementId(engagement.id)}
               >
                 <div className="p-4 flex flex-col h-full">
                    <div className="flex justify-between items-start mb-2">
                       <Badge {...getHealthBadgeProps(engagement.health)} size="sm">{engagement.health}</Badge>
                       <span className="text-[11px] font-bold text-on-surface-variant uppercase">{engagement.status}</span>
                    </div>
                    <h3 className="text-[16px] font-bold text-on-surface mb-1 truncate">{engagement.clientName}</h3>

                    {engagement.intelligenceSignal && (
                      <p className="text-[12px] font-medium text-on-surface-variant mb-3 bg-surface-container/50 p-2 rounded line-clamp-2">
                        {engagement.intelligenceSignal}
                      </p>
                    )}

                    <div className="mt-auto pt-2 border-t border-outline-variant/30 text-[12px] text-on-surface flex justify-between">
                       <span className="flex items-center gap-1 opacity-80"><span className="material-symbols-outlined text-[14px]">event</span> {new Date(engagement.lastInteractionDate).toLocaleDateString()}</span>
                       <span className="flex items-center gap-1 font-medium">{engagement.owner}</span>
                    </div>
                 </div>
               </Card>
            ))}
          </div>
        ) : (
          <div className="text-center p-8 bg-surface-container rounded-xl border border-outline-variant text-on-surface-variant">
            <span className="material-symbols-outlined text-[32px] mb-2 text-success">verified</span>
            <p className="font-semibold text-on-surface text-[14.5px] mb-1">Clear</p>
            <p className="text-[13px]">No active engagements require immediate attention.</p>
          </div>
        )}
      </section>

      {/* -------------------- ALL ENGAGEMENTS LIST -------------------- */}
      <section>
         <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant mb-4">All Active Relationships</h2>
         {localData.engagements.length > 0 ? (
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
             {localData.engagements.map(engagement => (
               <div 
                 key={`all-${engagement.id}`}
                 onClick={() => setSelectedEngagementId(engagement.id)}
                 className="cursor-pointer border border-outline-variant bg-surface rounded-xl p-4 transition-colors hover:border-primary shrink-0 flex flex-col"
               >
                 <div className="mb-2">
                   <h4 className="font-bold text-[15px] truncate text-on-surface">{engagement.clientName}</h4>
                 </div>
                 <div className="flex gap-2 items-center mb-3">
                   <span className={`w-2 h-2 rounded-full ${engagement.health === 'HEALTHY' ? 'bg-success' : engagement.health === 'AT_RISK' ? 'bg-error' : 'bg-warning'}`}></span>
                   <span className="text-[12.5px] text-on-surface-variant font-medium">{engagement.health}</span>
                 </div>
                 <div className="mt-auto">
                    <p className="text-[11.5px] text-on-surface-variant uppercase tracking-wide">Last Sync: {new Date(engagement.lastInteractionDate).toLocaleDateString()}</p>
                 </div>
               </div>
             ))}
           </div>
         ) : (
           <EmptyState 
              icon="supervisor_account"
              title="No Relationships"
              description="There are currently no retention engagements managed in the OS."
           />
         )}
      </section>

      {/* -------------------- ENGAGEMENT DETAIL MODAL / WORKSPACE -------------------- */}
      <Modal isOpen={!!selectedEngagementId} onClose={() => { setSelectedEngagementId(null); setIsEditingEngagement(false); setIsAddingInteraction(false); }} title="Retention Details" size="lg">
         {activeEngagement ? (
           <div className="flex flex-col gap-8 pb-4">

              {/* Alert Render */}
              {mutationError && (
                 <Alert variant="danger" title="Mutation Failure">
                   {mutationError}
                   <div className="mt-3">
                     <Button variant="secondary" size="sm" onClick={() => setMutationError(null)}>Dismiss</Button>
                   </div>
                 </Alert>
              )}

              {/* Header Context */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-outline-variant pb-4">
                 <div>
                   <div className="flex gap-2 items-center mb-1">
                     <Badge {...getHealthBadgeProps(activeEngagement.health)} size="sm">{activeEngagement.health}</Badge>
                     {activeEngagement.intelligenceSignal && (
                        <div className="bg-primary/5 text-primary text-[12px] font-medium px-2 py-0.5 rounded-full flex items-center gap-1">
                           <span className="material-symbols-outlined text-[14px]">insights</span>
                           {activeEngagement.intelligenceSignal}
                        </div>
                     )}
                   </div>
                   <h2 className="text-[24px] font-display font-bold text-on-surface mt-2">{activeEngagement.clientName}</h2>
                   <p className="text-[14px] text-on-surface-variant">{activeEngagement.status.replace("_", " ")}</p>
                 </div>

                 <div className="flex flex-col md:items-end gap-1 text-[13px] bg-surface-container rounded-lg p-3">
                    <div className="flex items-center gap-2 text-on-surface-variant">
                      <span className="material-symbols-outlined text-[16px]">how_to_reg</span>
                      <span className="font-medium">Owner: {activeEngagement.owner}</span>
                    </div>
                    <div className="flex items-center gap-2 text-on-surface-variant mt-1">
                      <span className="material-symbols-outlined text-[16px]">restore</span>
                      <span className="font-medium">Started: {new Date(activeEngagement.startDate).toLocaleDateString()}</span>
                    </div>
                 </div>
              </div>

              {/* Relationship Summary Edit Form */}
              <section className="bg-surface border border-outline-variant rounded-xl p-5 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                   <h3 className="font-bold text-[15px] uppercase tracking-wider flex items-center gap-2 text-on-surface-variant">
                     <span className="material-symbols-outlined text-[18px]">article</span> Relationship Summary
                   </h3>
                   {!isEditingEngagement ? (
                     <Button variant="secondary" size="sm" onClick={handleEditEngagement}>Edit Health</Button>
                   ) : (
                     <div className="flex gap-2">
                       <Button variant="secondary" size="sm" onClick={handleCancelEdit} disabled={isSaving}>Cancel</Button>
                       <Button variant="primary" size="sm" onClick={handleSaveEngagement} isLoading={isSaving}>Save</Button>
                     </div>
                   )}
                </div>

                {!isEditingEngagement ? (
                   <p className="text-[14.5px] text-on-surface leading-relaxed whitespace-pre-wrap">{activeEngagement.relationshipSummary}</p>
                ) : (
                   <div className="space-y-4">
                      <FormField label="Relationship Summary">
                        <Textarea 
                          value={engagementDraft?.relationshipSummary || ""} 
                          onChange={(e) => setEngagementDraft(prev => prev ? {...prev, relationshipSummary: e.target.value} : null)}
                          rows={4}
                        />
                      </FormField>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="Health Indicator">
                          <Select
                            value={engagementDraft?.health || "HEALTHY"}
                            onChange={(e) => setEngagementDraft(prev => prev ? {...prev, health: e.target.value as any} : null)}
                          >
                            <option value="HEALTHY">HEALTHY</option>
                            <option value="WATCH">WATCH</option>
                            <option value="AT_RISK">AT RISK</option>
                          </Select>
                        </FormField>
                        <FormField label="Retention Status">
                          <Select
                            value={engagementDraft?.status || "HEALTHY"}
                            onChange={(e) => setEngagementDraft(prev => prev ? {...prev, status: e.target.value as any} : null)}
                          >
                            <option value="NOT_STARTED">NOT STARTED</option>
                            <option value="HEALTHY">HEALTHY</option>
                            <option value="NEEDS_ATTENTION">NEEDS ATTENTION</option>
                            <option value="AT_RISK">AT RISK</option>
                            <option value="COMPLETED">COMPLETED</option>
                          </Select>
                        </FormField>
                      </div>
                   </div>
                )}
              </section>

              {/* Next Action Module */}
              <section>
                 <h3 className="font-bold text-[15px] uppercase tracking-wider mb-4 border-b border-outline-variant pb-2">Next Step / Action</h3>
                 {activeEngagement.nextAction ? (
                   <div className={`p-4 rounded-xl border ${activeEngagement.nextAction.status === 'COMPLETED' ? 'bg-success/5 border-success/30' : 'bg-surface border-outline-variant'} flex flex-col md:flex-row justify-between items-start md:items-center gap-4`}>
                      <div className="flex-1">
                         <div className="flex items-center gap-2 mb-1">
                           <Badge variant={activeEngagement.nextAction.status === 'COMPLETED' ? 'success' : 'neutral'} size="sm">
                             {activeEngagement.nextAction.status.replace("_", " ")}
                           </Badge>
                           <h4 className="font-bold text-[15px] text-on-surface">{activeEngagement.nextAction.title}</h4>
                         </div>
                         <p className="text-[14px] text-on-surface-variant mb-2">{activeEngagement.nextAction.description}</p>
                         <div className="flex items-center gap-3 text-[12px] font-medium text-on-surface">
                            <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">event</span> {new Date(activeEngagement.nextAction.dueDate).toLocaleDateString()}</span>
                            <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">person</span> {activeEngagement.nextAction.owner}</span>
                         </div>
                      </div>
                      <div className="md:min-w-[120px] text-right">
                         {activeEngagement.nextAction.status !== "COMPLETED" && (
                           <Button variant="secondary" size="sm" onClick={() => setConfirmActionComplete({ engagementId: activeEngagement.id, actionId: activeEngagement.nextAction!.id })}>
                             Mark Delivered
                           </Button>
                         )}
                      </div>
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant">
                      No explicit next action is currently scheduled.
                   </div>
                 )}
              </section>

              {/* Active Risks */}
              <section>
                <div className="flex items-center gap-2 mb-4 border-b border-outline-variant pb-2">
                   <h3 className="font-bold text-[15px] uppercase tracking-wider">Active Risks</h3>
                   {activeEngagement.risks.filter(r => r.status === "OPEN").length > 0 && (
                     <Badge variant="danger" size="sm" className="rounded-full w-5 h-5 flex items-center justify-center p-0 ml-1">
                       {activeEngagement.risks.filter(r => r.status === "OPEN").length}
                     </Badge>
                   )}
                </div>
                {activeEngagement.risks.length > 0 ? (
                  <div className="space-y-3">
                    {activeEngagement.risks.map(r => (
                      <div key={r.id} className={`p-4 rounded-xl border flex flex-col md:flex-row justify-between items-start gap-4 ${r.status !== 'RESOLVED' && r.severity === 'HIGH' ? 'bg-error/5 border-error/30' : 'bg-surface border-outline-variant'}`}>
                         <div>
                            <div className="flex gap-2 items-center mb-2">
                              {r.status === 'RESOLVED' ? (
                                <Badge variant="success" size="sm">RESOLVED</Badge>
                              ) : (
                                <Badge variant={r.severity === 'HIGH' ? 'danger' : r.severity === 'MEDIUM' ? 'warning' : 'neutral'} size="sm">
                                  {r.severity} RISK
                                </Badge>
                              )}
                              <h4 className={`font-bold text-[14.5px] ${r.status === 'RESOLVED' ? 'line-through opacity-70' : 'text-on-surface'}`}>{r.title}</h4>
                            </div>
                            <p className="text-[13.5px] text-on-surface-variant">{r.description}</p>
                            {r.recommendedAction && r.status !== 'RESOLVED' && (
                              <p className="mt-2 text-[12px] bg-surface font-medium p-2 rounded border border-outline-variant">Remediation: {r.recommendedAction}</p>
                            )}
                         </div>
                         {r.status !== 'RESOLVED' && (
                           <div className="self-end md:self-start">
                             <Button variant="secondary" size="sm" onClick={() => setConfirmRiskResolve({ engagementId: activeEngagement.id, riskId: r.id })}>
                               Resolve
                             </Button>
                           </div>
                         )}
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant flex flex-col items-center">
                     <span className="material-symbols-outlined text-[24px] mb-2 text-success">verified_user</span>
                     No open retention risks logged.
                  </div>
                )}
              </section>

              {/* Interactions Log */}
              <section>
                 <div className="flex justify-between items-center mb-4 border-b border-outline-variant pb-2">
                   <h3 className="font-bold text-[15px] uppercase tracking-wider flex items-center gap-2">
                     <span className="material-symbols-outlined text-[18px]">forum</span> Interaction History
                   </h3>
                   {!isAddingInteraction && <Button variant="secondary" size="sm" onClick={handleStartAddInteraction}>Log Event</Button>}
                 </div>

                 {isAddingInteraction && (
                   <div className="bg-primary/5 border border-primary/20 rounded-xl p-5 mb-5 space-y-4">
                     <div className="grid grid-cols-2 gap-4">
                       <FormField label="Event Type">
                         <Select 
                           value={interactionDraft?.type || "CHECK_IN"}
                           onChange={(e) => setInteractionDraft(prev => prev ? {...prev, type: e.target.value as any} : null)}
                         >
                           <option value="CALL">Call</option>
                           <option value="EMAIL">Email</option>
                           <option value="MEETING">Meeting</option>
                           <option value="CHECK_IN">Check-in</option>
                           <option value="DELIVERY_UPDATE">Delivery Update</option>
                           <option value="OTHER">Other</option>
                         </Select>
                       </FormField>
                       <FormField label="Owner">
                         <Input 
                           value={interactionDraft?.owner || ""}
                           onChange={(e) => setInteractionDraft(prev => prev ? {...prev, owner: e.target.value} : null)}
                         />
                       </FormField>
                     </div>
                     <FormField label="Interaction Summary (Required)">
                       <Textarea 
                         required
                         value={interactionDraft?.summary || ""}
                         onChange={(e) => setInteractionDraft(prev => prev ? {...prev, summary: e.target.value} : null)}
                         rows={2}
                       />
                     </FormField>
                     <FormField label="Outcome (Optional)">
                       <Input 
                         value={interactionDraft?.outcome || ""}
                         onChange={(e) => setInteractionDraft(prev => prev ? {...prev, outcome: e.target.value} : null)}
                       />
                     </FormField>
                     <div className="flex justify-end gap-2 pt-2">
                       <Button variant="secondary" onClick={handleCancelAddInteraction} disabled={isSaving}>Cancel</Button>
                       <Button variant="primary" onClick={handleSaveInteraction} isLoading={isSaving}>Save Event</Button>
                     </div>
                   </div>
                 )}

                 {activeEngagement.interactions.length > 0 ? (
                   <div className="relative border-l-2 border-outline-variant/50 ml-3 space-y-6 pb-2">
                     {activeEngagement.interactions.map(interaction => (
                       <div key={interaction.id} className="relative pl-6">
                         <div className="absolute -left-[9px] top-1 w-4 h-4 rounded-full bg-surface border-2 border-primary z-10 shadow-sm"></div>
                         <div className="bg-surface border border-outline-variant rounded-lg p-4 shadow-sm hover:border-outline transition-colors">
                           <div className="flex justify-between items-start mb-2">
                             <div className="flex gap-2 items-center">
                               <Badge variant="neutral" size="sm">{interaction.type}</Badge>
                               <span className="text-[12px] font-bold text-on-surface">{interaction.owner}</span>
                             </div>
                             <span className="text-[11.5px] text-on-surface-variant">{new Date(interaction.date).toLocaleString()}</span>
                           </div>
                           <p className="text-[14px] text-on-surface bg-surface-container-low p-2 rounded leading-relaxed">{interaction.summary}</p>
                           {interaction.outcome && (
                             <p className="mt-2 text-[12.5px] font-medium text-success flex items-center gap-1">
                               <span className="material-symbols-outlined text-[14px]">done_all</span> {interaction.outcome}
                             </p>
                           )}
                         </div>
                       </div>
                     ))}
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant">
                      No relationship interactions have been logged.
                   </div>
                 )}
              </section>

              {/* Goals */}
              <section>
                 <h3 className="font-bold text-[15px] uppercase tracking-wider mb-4 border-b border-outline-variant pb-2 text-on-surface-variant flex items-center gap-2">
                    <span className="material-symbols-outlined text-[18px]">flag</span> Desired Outcomes (Goals)
                 </h3>
                 {activeEngagement.goals.length > 0 ? (
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                     {activeEngagement.goals.map(goal => (
                       <div key={goal.id} className="bg-surface border border-outline-variant rounded-xl p-4 flex flex-col justify-between">
                         <div>
                            <div className="flex justify-between items-start mb-2">
                              <Badge variant={goal.status === 'ACHIEVED' ? 'success' : goal.status === 'AT_RISK' ? 'warning' : 'neutral'} size="sm">
                                {goal.status.replace("_", " ")}
                              </Badge>
                              <span className="text-[12px] font-medium text-on-surface-variant">{goal.id}</span>
                            </div>
                            <h4 className="font-bold text-[14.5px] text-on-surface mb-1">{goal.title}</h4>
                            <p className="text-[13px] text-on-surface-variant mb-3">{goal.description}</p>
                         </div>
                         <div className="mt-2 bg-surface-container-low border border-outline p-2 rounded">
                           <span className="block text-[10px] uppercase font-bold text-on-surface-variant mb-1">Current State</span>
                           <span className="text-[13.5px] font-medium text-on-surface">{goal.currentState}</span>
                         </div>
                         <div className="mt-3 flex justify-between items-center text-[12px] text-on-surface-variant">
                           <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">person</span> {goal.owner}</span>
                           <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">event</span> {new Date(goal.targetDate).toLocaleDateString()}</span>
                         </div>
                       </div>
                     ))}
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant">
                      No goals have been defined for this customer.
                   </div>
                 )}
              </section>

           </div>
         ) : <Skeleton className="h-64 w-full" />}
      </Modal>

      {/* -------------------- DESTRUCTIVE/IMPORTANT CONFIRMATIONS -------------------- */}
      <ConfirmationDialog
        isOpen={!!confirmRiskResolve}
        onClose={() => { if (!isSaving) setConfirmRiskResolve(null); }}
        onConfirm={executeRiskResolution}
        title="Resolve Risk"
        description="Are you sure you want to mark this structural relationship risk as resolved?"
        confirmText="Confirm Resolution"
        isDestructive={false}
        isLoading={isSaving}
      />

      <ConfirmationDialog
        isOpen={!!confirmActionComplete}
        onClose={() => { if (!isSaving) setConfirmActionComplete(null); }}
        onConfirm={executeActionCompletion}
        title="Complete Next Action"
        description="Are you sure you want to clear the pending next action for this relationship?"
        confirmText="Clear Action"
        isDestructive={false}
        isLoading={isSaving}
      />

    </div>
  );
}

"use client";

import React, { useState, useEffect } from "react";
import { 
  getRevenue, 
  updateRevenueEngagement, 
  updateRevenueItem,
  resolveRevenueRisk,
  updateRevenueNextAction
} from "@/lib/adapters";
import { 
  RevenueData, 
  RevenueEngagement,
  RevenueItem,
  RevenueStatus
} from "@/lib/types";

import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Modal } from "@/components/ui/Modal";
import { Input, Textarea, Select, FormField } from "@/components/ui/Forms";
import { Skeleton, CardSkeleton, EmptyState } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { ConfirmationDialog } from "@/components/ui/ConfirmationDialog";

function formatCurrency(amount: number, currency: string) {
  return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(amount);
}

function getStatusBadgeContext(status: string) {
  switch (status) {
    case "COLLECTED":
    case "PAID":
      return { variant: "success" as const };
    case "AT_RISK":
    case "OVERDUE":
      return { variant: "danger" as const };
    case "INVOICED":
    case "DUE":
    case "ON_TRACK":
    case "PARTIAL":
      return { variant: "warning" as const };
    default:
      return { variant: "neutral" as const };
  }
}

export default function RevenueWorkspace() {
  const [data, setData] = useState<RevenueData | null>(null);
  const [localData, setLocalData] = useState<RevenueData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [mutationError, setMutationError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Detail Modal setup
  const [selectedEngagementId, setSelectedEngagementId] = useState<string | null>(null);
  const activeEngagement = localData?.engagements.find(e => e.id === selectedEngagementId);

  // Edit Context buffer
  const [isEditingRevenue, setIsEditingRevenue] = useState(false);
  const [revenueDraft, setRevenueDraft] = useState<RevenueEngagement | null>(null);

  // Confirmation actions
  const [confirmRiskResolve, setConfirmRiskResolve] = useState<{ engagementId: string, riskId: string } | null>(null);
  const [confirmActionComplete, setConfirmActionComplete] = useState<{ engagementId: string, actionId: string } | null>(null);
  const [confirmItemCollect, setConfirmItemCollect] = useState<{ engagementId: string, item: RevenueItem } | null>(null);

  async function loadData() {
    setLoading(true);
    setError(null);
    try {
      const res = await getRevenue();
      setData(res);
      setLocalData(res);
    } catch (err: unknown) {
      setError((err as Error).message);
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  // --------------- CONTEXT EDIT PIPELINE ---------------
  function handleEditRevenue() {
    if (!activeEngagement) return;
    setMutationError(null);
    setRevenueDraft({ ...activeEngagement });
    setIsEditingRevenue(true);
  }

  function handleCancelEdit() {
    setMutationError(null);
    setRevenueDraft(null);
    setIsEditingRevenue(false);
  }

  async function handleSaveRevenue() {
    if (!revenueDraft) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateRevenueEngagement(revenueDraft);
      setLocalData(res);
      setData(res);
      setIsEditingRevenue(false);
      setRevenueDraft(null);
    } catch (err: unknown) {
      setMutationError("Failed to save operational context: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- ITEM COLLECTION PIPELINE ---------------
  async function executeItemCollection() {
    if (!confirmItemCollect || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const payload: RevenueItem = { ...confirmItemCollect.item, status: "COLLECTED" };
      const res = await updateRevenueItem(confirmItemCollect.engagementId, payload);
      setLocalData(res);
      setData(res);
      setConfirmItemCollect(null);
    } catch (err: unknown) {
      setMutationError("Failed to update item state: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- RISK RESOLUTION PIPELINE ---------------
  async function executeRiskResolution() {
    if (!confirmRiskResolve || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await resolveRevenueRisk(confirmRiskResolve.engagementId, confirmRiskResolve.riskId);
      setLocalData(res);
      setData(res);
      setConfirmRiskResolve(null);
    } catch(err: unknown) {
      setMutationError("Failed to resolve risk: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  // --------------- ACTION COMPLETION PIPELINE ---------------
  async function executeActionCompletion() {
    if (!confirmActionComplete || !localData) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateRevenueNextAction(confirmActionComplete.engagementId, confirmActionComplete.actionId);
      setLocalData(res);
      setData(res);
      setConfirmActionComplete(null);
    } catch(err: unknown) {
      setMutationError("Failed to complete action: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  if (loading) {
    return (
      <div className="max-w-[1400px] mx-auto p-6 md:p-8 animate-in fade-in duration-500 space-y-8">
        <header className="mb-6">
          <Skeleton className="h-8 w-48 mb-2" />
          <Skeleton className="h-4 w-64" />
        </header>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  if (error || !localData) {
    return (
      <div className="max-w-[800px] mx-auto mt-12">
        <Alert variant="danger" title="Failed to load Revenue Data">
          {error}
          <div className="mt-4">
            <Button variant="secondary" onClick={loadData}>Retry</Button>
          </div>
        </Alert>
      </div>
    );
  }

  const needingAttention = localData.engagements.filter(e => 
    e.status === "AT_RISK" || 
    e.status === "OVERDUE" || 
    e.risks.some(r => r.status === "OPEN")
  );

  const activeRevenue = localData.engagements.filter(e => 
    e.status === "ON_TRACK" || e.status === "NOT_STARTED"
  );

  const completedRevenue = localData.engagements.filter(e => e.status === "COLLECTED");

  return (
    <div className="max-w-[1400px] mx-auto p-6 md:p-8 space-y-10 animate-in fade-in duration-500">

      {/* -------------------- HEADER -------------------- */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-[28px] font-display font-medium text-on-surface tracking-tight">Revenue Operations</h1>
          <p className="text-on-surface-variant text-[15px] mt-1">Operational view of billing, active collections, and revenue risks.</p>
        </div>
        <div className="flex bg-surface border border-outline-variant rounded-[var(--radius-lg)] p-1 text-center shadow-sm">
           <div className="px-5 py-2 border-r border-outline-variant uppercase">
             <span className="block text-[11px] font-bold text-error tracking-wider mb-0.5">At Risk / Overdue</span>
             <span className="text-[17px] font-display font-bold text-on-surface">{needingAttention.length}</span>
           </div>
           <div className="px-5 py-2 uppercase">
             <span className="block text-[11px] font-bold text-on-surface-variant tracking-wider mb-0.5">Active</span>
             <span className="text-[17px] font-display font-bold text-on-surface">{activeRevenue.length}</span>
           </div>
        </div>
      </header>

      {/* -------------------- ATTENTION REQUIRED -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-error text-[20px]">warning</span>
           <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant">Attention Required</h2>
        </div>

        {needingAttention.length > 0 ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {needingAttention.map(engagement => (
               <Card 
                key={`urgent-${engagement.id}`} 
                className="cursor-pointer transition-shadow hover:shadow-md border-error/30 ring-1 ring-error/20 bg-error/5"
                onClick={() => setSelectedEngagementId(engagement.id)}
               >
                 <div className="p-5 flex flex-col h-full">
                    <div className="flex justify-between items-start mb-2">
                       <Badge {...getStatusBadgeContext(engagement.status)} size="sm">{engagement.status.replace("_", " ")}</Badge>
                       <span className="text-[14.5px] font-display font-bold text-on-surface">
                         {formatCurrency(engagement.amount, engagement.currency)}
                       </span>
                    </div>
                    <h3 className="text-[16px] font-bold text-on-surface mb-1 truncate">{engagement.customerName}</h3>
                    <p className="text-[13px] text-on-surface-variant mb-4">{engagement.description}</p>

                    {engagement.intelligenceSignal && (
                      <div className="mb-3 bg-error/10 text-[12px] font-medium text-error p-2 rounded flex items-start gap-1">
                        <span className="material-symbols-outlined text-[14px]">insights</span>
                        <span className="leading-tight">{engagement.intelligenceSignal}</span>
                      </div>
                    )}

                    <div className="mt-auto pt-3 border-t border-error/20 text-[12px] text-on-surface flex justify-between items-center">
                       <span className="flex items-center gap-1 font-medium"><span className="material-symbols-outlined text-[14px]">event</span> Due: {new Date(engagement.dueDate).toLocaleDateString()}</span>
                       <span className="flex items-center gap-1 font-bold text-on-surface-variant">{engagement.owner}</span>
                    </div>
                 </div>
               </Card>
            ))}
          </div>
        ) : (
          <div className="text-center p-8 bg-surface-container rounded-xl border border-outline-variant text-on-surface-variant flex flex-col items-center">
            <span className="material-symbols-outlined text-[32px] mb-2 text-success">verified</span>
            <p className="font-semibold text-on-surface text-[14.5px] mb-1">Clear</p>
            <p className="text-[13px]">No revenue items require attention.</p>
          </div>
        )}
      </section>

      {/* -------------------- ACTIVE REVENUE -------------------- */}
      <section>
         <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant mb-4">Active Revenue (On Track)</h2>
         {activeRevenue.length > 0 ? (
           <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
             {activeRevenue.map(engagement => (
               <div 
                 key={`active-${engagement.id}`}
                 onClick={() => setSelectedEngagementId(engagement.id)}
                 className="cursor-pointer border border-outline-variant bg-surface rounded-xl p-5 transition-colors hover:border-primary shrink-0 flex flex-col"
               >
                 <div className="flex justify-between items-start mb-2">
                   <h4 className="font-bold text-[16px] truncate text-on-surface">{engagement.customerName}</h4>
                   <span className="text-[14px] font-display font-medium text-on-surface-variant">{formatCurrency(engagement.amount, engagement.currency)}</span>
                 </div>
                 <div className="flex gap-2 items-center mb-3">
                   <Badge {...getStatusBadgeContext(engagement.status)} size="sm">{engagement.status.replace("_", " ")}</Badge>
                   <span className="text-[11px] font-bold text-on-surface-variant uppercase">{engagement.paymentState}</span>
                 </div>
                 <div className="mt-3 pt-3 border-t border-outline-variant flex items-center justify-between text-[11.5px] text-on-surface-variant uppercase tracking-wide">
                    <span>Due: {new Date(engagement.dueDate).toLocaleDateString()}</span>
                    <span>{engagement.items.filter(i => i.status !== "COLLECTED").length} Pending Items</span>
                 </div>
               </div>
             ))}
           </div>
         ) : (
           <div className="text-center p-8 bg-surface-container rounded-xl border border-outline-variant text-on-surface-variant">
             <p className="text-[13px]">No active revenue items.</p>
           </div>
         )}
      </section>

      {/* -------------------- COMPLETED / COLLECTED -------------------- */}
      <section>
         <h2 className="text-[13.5px] uppercase font-bold tracking-wider text-on-surface-variant mb-4">Recently Collected</h2>
         {completedRevenue.length > 0 ? (
           <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
             {completedRevenue.map(eng => (
                <div key={`comp-${eng.id}`} onClick={() => setSelectedEngagementId(eng.id)} className="cursor-pointer bg-surface-container border border-outline-variant rounded-lg p-3 flex justify-between items-center transition-colors hover:bg-surface-container-high">
                  <div>
                    <h5 className="font-bold text-[13.5px] text-on-surface">{eng.customerName}</h5>
                    <p className="text-[11.5px] text-on-surface-variant">{eng.description}</p>
                  </div>
                  <div className="text-right">
                    <span className="block font-medium text-[13px] text-success">{formatCurrency(eng.amount, eng.currency)}</span>
                  </div>
                </div>
             ))}
           </div>
         ) : (
           <div className="text-center p-6 bg-surface-container rounded-lg border border-outline-variant text-on-surface-variant text-[13px]">
             No recently completed revenue cycles.
           </div>
         )}
      </section>

      {/* -------------------- DETAIL MODAL -------------------- */}
      <Modal isOpen={!!selectedEngagementId} onClose={() => { setSelectedEngagementId(null); setIsEditingRevenue(false); }} title="Revenue Detail" size="lg">
         {activeEngagement ? (
           <div className="flex flex-col gap-8 pb-4">

              {/* Alert Render */}
              {mutationError && (
                 <Alert variant="danger" title="Action Failed">
                   {mutationError}
                   <div className="mt-3">
                     <Button variant="secondary" size="sm" onClick={() => setMutationError(null)}>Dismiss</Button>
                   </div>
                 </Alert>
              )}

              {/* Header Context */}
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-outline-variant pb-5">
                 <div>
                   <h2 className="text-[26px] font-display font-bold text-on-surface">{activeEngagement.customerName}</h2>
                   <p className="text-[15px] font-medium text-on-surface-variant mt-1">{activeEngagement.description}</p>
                   {activeEngagement.linkedContext && (
                     <p className="mt-2 text-[12.5px] text-on-surface bg-surface-container-low px-2 py-1 rounded inline-flex items-center gap-1 border border-outline-variant"><span className="material-symbols-outlined text-[14px]">link</span> {activeEngagement.linkedContext}</p>
                   )}
                 </div>

                 <div className="text-left md:text-right">
                    <p className="text-[28px] font-display font-bold text-on-surface">{formatCurrency(activeEngagement.amount, activeEngagement.currency)}</p>
                    <div className="flex items-center md:justify-end gap-2 mt-1">
                      <Badge {...getStatusBadgeContext(activeEngagement.status)} size="sm">{activeEngagement.status.replace("_", " ")}</Badge>
                      <Badge variant="neutral" size="sm">{activeEngagement.paymentState}</Badge>
                    </div>
                 </div>
              </div>

              {/* Intelligence/Error Signal Context */}
              {activeEngagement.intelligenceSignal && (
                <div className="bg-primary/5 text-primary text-[13.5px] font-medium px-4 py-3 rounded-lg flex items-start gap-2 border border-primary/20">
                    <span className="material-symbols-outlined mt-0.5">insights</span>
                    <span className="leading-relaxed">System Intelligence: {activeEngagement.intelligenceSignal}</span>
                </div>
              )}

              {/* Read / Edit Boundary */}
              <section className="bg-surface border border-outline-variant rounded-xl p-5 shadow-sm">
                <div className="flex justify-between items-center mb-4">
                   <h3 className="font-bold text-[15px] uppercase tracking-wider flex items-center gap-2 text-on-surface-variant">
                     <span className="material-symbols-outlined text-[18px]">tune</span> Revenue Context
                   </h3>
                   {!isEditingRevenue ? (
                     <Button variant="secondary" size="sm" onClick={handleEditRevenue}>Edit Context</Button>
                   ) : (
                     <div className="flex gap-2">
                       <Button variant="secondary" size="sm" onClick={handleCancelEdit} disabled={isSaving}>Cancel</Button>
                       <Button variant="primary" size="sm" onClick={handleSaveRevenue} isLoading={isSaving}>Save Context</Button>
                     </div>
                   )}
                </div>

                {!isEditingRevenue ? (
                   <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-[13.5px]">
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Owner</span>
                       <span className="font-medium text-on-surface">{activeEngagement.owner}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Expected Date</span>
                       <span className="font-medium text-on-surface">{new Date(activeEngagement.dueDate).toLocaleDateString()}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Status</span>
                       <span className="font-medium text-on-surface">{activeEngagement.status.replace("_", " ")}</span>
                     </div>
                     <div>
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase mb-1">Payment State</span>
                       <span className="font-medium text-on-surface">{activeEngagement.paymentState}</span>
                     </div>
                   </div>
                ) : (
                   <div className="space-y-4">

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="Owner">
                           <Input 
                            value={revenueDraft?.owner || ""} 
                            onChange={(e) => setRevenueDraft(prev => prev ? {...prev, owner: e.target.value} : null)}
                           />
                        </FormField>
                        <FormField label="Payment State">
                          <Select
                            value={revenueDraft?.paymentState || "UNINVOICED"}
                            onChange={(e) => setRevenueDraft(prev => prev ? {...prev, paymentState: e.target.value as RevenueEngagement['paymentState']} : null)}
                          >
                            <option value="UNINVOICED">UNINVOICED</option>
                            <option value="INVOICED">INVOICED</option>
                            <option value="PARTIAL">PARTIAL</option>
                            <option value="PAID">PAID</option>
                          </Select>
                        </FormField>
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField label="Internal Status">
                          <Select
                            value={revenueDraft?.status || "ON_TRACK"}
                            onChange={(e) => setRevenueDraft(prev => prev ? {...prev, status: e.target.value as RevenueStatus} : null)}
                          >
                            <option value="NOT_STARTED">NOT STARTED</option>
                            <option value="ON_TRACK">ON TRACK</option>
                            <option value="AT_RISK">AT RISK</option>
                            <option value="OVERDUE">OVERDUE</option>
                            <option value="COLLECTED">COLLECTED</option>
                          </Select>
                        </FormField>
                        <FormField label="Due Date (YYYY-MM-DD)">
                           <Input 
                            value={revenueDraft ? new Date(revenueDraft.dueDate).toISOString().split('T')[0] : ""} 
                            type="date"
                            onChange={(e) => setRevenueDraft(prev => prev ? {...prev, dueDate: new Date(e.target.value).toISOString()} : null)}
                           />
                        </FormField>
                      </div>

                   </div>
                )}
              </section>

              {/* Outstanding / Collected Items Workflow */}
              <section>
                 <h3 className="font-bold text-[15px] uppercase tracking-wider mb-4 border-b border-outline-variant pb-2 flex items-center gap-2">
                   <span className="material-symbols-outlined text-[18px]">receipt_long</span> Revenue Records / Tranches
                 </h3>

                 {activeEngagement.items.length > 0 ? (
                   <div className="space-y-3">
                     {activeEngagement.items.map(item => (
                       <div key={item.id} className={`p-4 rounded-xl border flex flex-col md:flex-row justify-between items-start md:items-center gap-4 ${item.status === 'COLLECTED' ? 'bg-success/5 border-success/30' : 'bg-surface border-outline-variant'}`}>
                          <div className="flex-1">
                             <div className="flex items-center gap-2 mb-1">
                               <Badge {...getStatusBadgeContext(item.status)} size="sm">{item.status.replace("_", " ")}</Badge>
                               <span className="text-[12px] font-bold text-on-surface-variant tracking-wider uppercase border text-[10px] px-1 rounded-sm border-outline-variant">{item.id}</span>
                             </div>
                             <h4 className="font-bold text-[15px] text-on-surface mb-1 flex justify-between w-full pr-4">
                               {item.title} <span className="font-display ml-auto tracking-wide">{formatCurrency(item.amount, activeEngagement.currency)}</span>
                             </h4>
                             <p className="text-[13px] text-on-surface-variant mb-2">{item.description}</p>
                             <p className="text-[11.5px] font-medium text-on-surface flex items-center gap-1 opacity-70">
                               <span className="material-symbols-outlined text-[13px]">event</span> {item.status === 'COLLECTED' ? 'Collected on' : 'Due'}: {new Date(item.dueDate).toLocaleDateString()}
                             </p>
                          </div>
                          <div className="w-full md:w-auto text-right border-t md:border-t-0 md:border-l border-outline-variant pt-3 md:pt-0 md:pl-4 mt-2 md:mt-0">
                             {item.status !== "COLLECTED" && (
                               <Button variant="secondary" size="sm" onClick={() => setConfirmItemCollect({ engagementId: activeEngagement.id, item })}>
                                 Mark Collected
                               </Button>
                             )}
                          </div>
                       </div>
                     ))}
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant">
                      No revenue records are available.
                   </div>
                 )}
              </section>

              {/* Active Risks */}
              <section>
                 <div className="flex items-center gap-2 mb-4 border-b border-outline-variant pb-2">
                    <h3 className="font-bold text-[15px] uppercase tracking-wider">Revenue Risks</h3>
                 </div>
                 {activeEngagement.risks.length > 0 ? (
                   <div className="space-y-3">
                     {activeEngagement.risks.map(r => (
                       <div key={r.id} className={`p-4 rounded-xl border flex flex-col md:flex-row justify-between items-start gap-4 ${r.status !== 'RESOLVED' ? 'bg-error/5 border-error/30' : 'bg-surface border-outline-variant'}`}>
                          <div>
                             <div className="flex gap-2 items-center mb-2">
                               {r.status === 'RESOLVED' ? (
                                 <Badge variant="success" size="sm">RESOLVED</Badge>
                               ) : (
                                 <Badge variant="danger" size="sm">ACTIVE RISK</Badge>
                               )}
                               <span className={`font-bold text-[14.5px] ${r.status === 'RESOLVED' ? 'line-through opacity-70' : 'text-on-surface'}`}>{r.title}</span>
                             </div>
                             <p className="text-[13.5px] text-on-surface-variant max-w-[500px]">{r.description}</p>
                          </div>
                          {r.status !== 'RESOLVED' && (
                            <div className="self-end md:self-start shrink-0">
                              <Button variant="secondary" size="sm" onClick={() => setConfirmRiskResolve({ engagementId: activeEngagement.id, riskId: r.id })}>
                                Resolve Risk
                              </Button>
                            </div>
                          )}
                       </div>
                     ))}
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant flex flex-col items-center">
                      <span className="material-symbols-outlined text-[24px] mb-2 text-success">verified_user</span>
                      No revenue risks require attention.
                   </div>
                 )}
              </section>

              {/* Next Action Module */}
              <section>
                 <h3 className="font-bold text-[15px] uppercase tracking-wider mb-4 border-b border-outline-variant pb-2">Operational Next Action</h3>
                 {activeEngagement.nextAction ? (
                   <div className={`p-4 rounded-xl border flex flex-col md:flex-row justify-between items-start md:items-center gap-4 ${activeEngagement.nextAction.status === 'COMPLETED' ? 'bg-success/5 border-success/30' : 'bg-surface border-outline-variant'}`}>
                      <div className="flex-1">
                         <div className="flex items-center gap-2 mb-1">
                           <Badge variant={activeEngagement.nextAction.status === 'COMPLETED' ? 'success' : 'neutral'} size="sm">
                             {activeEngagement.nextAction.status}
                           </Badge>
                           <h4 className="font-bold text-[15px] text-on-surface">{activeEngagement.nextAction.title}</h4>
                         </div>
                         <p className="text-[14px] text-on-surface-variant mb-2">{activeEngagement.nextAction.description}</p>
                         <div className="flex items-center gap-3 text-[12px] font-medium text-on-surface opacity-80">
                            <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">event</span> Due: {new Date(activeEngagement.nextAction.dueDate).toLocaleDateString()}</span>
                            <span className="flex items-center gap-1"><span className="material-symbols-outlined text-[14px]">person</span> {activeEngagement.nextAction.owner}</span>
                         </div>
                      </div>
                      <div className="shrink-0 mt-3 md:mt-0 text-right w-full md:w-auto">
                         {activeEngagement.nextAction.status !== "COMPLETED" && (
                           <Button variant="secondary" size="sm" onClick={() => setConfirmActionComplete({ engagementId: activeEngagement.id, actionId: activeEngagement.nextAction!.id })}>
                             Mark Delivered
                           </Button>
                         )}
                      </div>
                   </div>
                 ) : (
                   <div className="text-center p-6 bg-surface-container rounded-xl border border-outline-variant text-[14px] text-on-surface-variant">
                      No next actions are currently pending.
                   </div>
                 )}
              </section>

           </div>
         ) : <Skeleton className="h-64 w-full" />}
      </Modal>

      {/* -------------------- DESTRUCTIVE/IMPORTANT CONFIRMATIONS -------------------- */}
      <ConfirmationDialog
        isOpen={!!confirmItemCollect}
        onClose={() => { if (!isSaving) setConfirmItemCollect(null); }}
        onConfirm={executeItemCollection}
        title="Confirm Revenue Collection"
        description={`Are you confirming that you have successfully collected the funds for ${confirmItemCollect?.item.title}?`}
        confirmText="Mark Collected"
        isDestructive={false}
        isLoading={isSaving}
      />

      <ConfirmationDialog
        isOpen={!!confirmRiskResolve}
        onClose={() => { if (!isSaving) setConfirmRiskResolve(null); }}
        onConfirm={executeRiskResolution}
        title="Resolve Revenue Risk"
        description="Are you sure you want to mark this revenue risk as resolved? This removes it from the attention workflow."
        confirmText="Confirm Resolution"
        isDestructive={false}
        isLoading={isSaving}
      />

      <ConfirmationDialog
        isOpen={!!confirmActionComplete}
        onClose={() => { if (!isSaving) setConfirmActionComplete(null); }}
        onConfirm={executeActionCompletion}
        title="Complete Next Action"
        description="Are you sure you want to mark the pending revenue action as delivered?"
        confirmText="Mark Delivered"
        isDestructive={false}
        isLoading={isSaving}
      />

    </div>
  );
}

"use client";

import React, { useState, useEffect, useCallback } from "react";
import { 
  getSettings, 
  updateSettings 
} from "@/lib/adapters";
import { 
  SettingsData,
  NotificationPriorityThreshold
} from "@/lib/types";

import { Card } from "@/components/ui/Card";
import { Button } from "@/components/ui/Button";
import { Input, Select, FormField } from "@/components/ui/Forms";
import { Skeleton, CardSkeleton } from "@/components/ui/States";
import { Alert } from "@/components/ui/Alert";
import { Badge } from "@/components/ui/Badge";
import { useAdapter } from "@/hooks/useAdapter";

export default function SettingsWorkspace() {
  const { data, setData, localData, setLocalData, loading, error, reload: loadData } = useAdapter(getSettings);

  const [mutationError, setMutationError] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  // Edit Buffer
  const [isEditing, setIsEditing] = useState(false);
  const [draftSettings, setDraftSettings] = useState<SettingsData | null>(null);

  // --------------- EDIT BOUNDARY ---------------
  function handleEdit() {
    if (!localData) return;
    setMutationError(null);
    setDraftSettings(JSON.parse(JSON.stringify(localData))); // Deep isolated copy
    setIsEditing(true);
  }

  function handleCancelEdit() {
    setMutationError(null);
    setDraftSettings(null);
    setIsEditing(false);
  }

  async function handleSaveSettings() {
    if (!draftSettings) return;
    setMutationError(null);
    setIsSaving(true);
    try {
      const res = await updateSettings(draftSettings);
      setLocalData(res);
      setData(res);
      setIsEditing(false);
      setDraftSettings(null);
    } catch (err: unknown) {
      setMutationError("Configuration persistence failed: " + (err as Error).message);
    } finally {
      setIsSaving(false);
    }
  }

  if (loading) {
    return (
      <div className="max-w-[1000px] mx-auto p-6 md:p-8 animate-in fade-in duration-500 space-y-8">
        <header className="mb-6">
          <Skeleton className="h-8 w-48 mb-2" />
          <Skeleton className="h-4 w-64" />
        </header>
        <div className="space-y-6">
          <CardSkeleton />
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  if (error || !localData) {
    return (
      <div className="max-w-[800px] mx-auto mt-12 p-6 md:p-8 space-y-10">
        <section>
          <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant mb-4">Diagnostic Recovery</h2>
          <Alert variant="danger" title="System Synchronization Failure">
            {error}
            <div className="mt-4">
              <Button variant="secondary" onClick={loadData}>Retry Connection</Button>
            </div>
          </Alert>
        </section>
      </div>
    );
  }

  // Active render state is strictly draft if editing, otherwise canonical localData.
  const renderData = isEditing && draftSettings ? draftSettings : localData;

  return (
    <div className="max-w-[1000px] mx-auto p-6 md:p-8 space-y-10 animate-in fade-in duration-500">

      {/* -------------------- HEADER -------------------- */}
      <header className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-outline-variant pb-6">
        <div>
          <h1 className="text-[28px] font-display font-medium text-on-surface tracking-tight">System Preferences</h1>
          <p className="text-on-surface-variant text-[15px] mt-1">Configure global application boundaries and operator profile.</p>
        </div>

        <div className="flex gap-2">
          {!isEditing ? (
            <Button variant="secondary" onClick={handleEdit}>Edit Preferences</Button>
          ) : (
            <>
              <Button variant="secondary" onClick={handleCancelEdit} disabled={isSaving}>Cancel</Button>
              <Button variant="primary" onClick={handleSaveSettings} isLoading={isSaving}>Save Preferences</Button>
            </>
          )}
        </div>
      </header>

      {/* Surface Mutation Error globally below header */}
      {mutationError && (
        <Alert variant="danger" title="Persistence Failure">
          {mutationError}
        </Alert>
      )}

      {/* -------------------- DIAGNOSTICS (Read Only) -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-primary text-[20px]">insights</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">System Diagnostics</h2>
        </div>
        <div className="bg-primary/5 text-[14px] font-medium text-primary-dark px-4 py-3 rounded-lg border border-primary/20 leading-relaxed shadow-sm">
           {localData.intelligenceSignal || "All systems operating optimally. No configuration adjustments recommended at this time."}
        </div>
      </section>

      {/* -------------------- USER PROFILE -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-on-surface-variant text-[20px]">person</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">Operator Profile</h2>
        </div>
        <Card className="p-6 md:p-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {!isEditing ? (
              <>
                <div className="space-y-1">
                  <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Display Name</span>
                  <p className="font-medium text-on-surface text-[15px]">{renderData.profile.displayName}</p>
                </div>
                <div className="space-y-1">
                  <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Role / Title</span>
                  <p className="font-medium text-on-surface text-[15px]">{renderData.profile.role}</p>
                </div>
                <div className="space-y-1">
                  <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Email Contact</span>
                  <p className="font-medium text-on-surface text-[15px]">{renderData.profile.email}</p>
                </div>
              </>
            ) : (
              <>
                <FormField label="Display Name">
                  <Input 
                    value={renderData.profile.displayName} 
                    onChange={e => setDraftSettings(prev => prev ? {...prev, profile: {...prev.profile, displayName: e.target.value}} : null)}
                  />
                </FormField>
                <FormField label="Role / Title">
                  <Input 
                    value={renderData.profile.role} 
                    onChange={e => setDraftSettings(prev => prev ? {...prev, profile: {...prev.profile, role: e.target.value}} : null)}
                  />
                </FormField>
                <FormField label="Email Contact">
                  <Input 
                    value={renderData.profile.email} 
                    type="email"
                    onChange={e => setDraftSettings(prev => prev ? {...prev, profile: {...prev.profile, email: e.target.value}} : null)}
                  />
                </FormField>
              </>
            )}
          </div>
        </Card>
      </section>

      {/* -------------------- NOTIFICATIONS -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-on-surface-variant text-[20px]">notifications</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">Notification Architecture</h2>
        </div>
        <Card className="p-6 md:p-8">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-8">

             {!isEditing ? (
                <>
                  <div className="space-y-4">
                    <h4 className="text-[12px] font-bold text-on-surface-variant uppercase border-b border-outline-variant pb-2">Channels Enabled</h4>
                    <div className="flex justify-between items-center bg-surface-container px-4 py-2.5 rounded-md border border-outline-variant">
                      <span className="text-[14px]">Email Alerts</span>
                      <Badge variant={renderData.notifications.emailAlertsEnabled ? "success" : "neutral"}>{renderData.notifications.emailAlertsEnabled ? "ACTIVE" : "OFF"}</Badge>
                    </div>
                    <div className="flex justify-between items-center bg-surface-container px-4 py-2.5 rounded-md border border-outline-variant">
                      <span className="text-[14px]">In-App Surface Alerts</span>
                      <Badge variant={renderData.notifications.inAppAlertsEnabled ? "success" : "neutral"}>{renderData.notifications.inAppAlertsEnabled ? "ACTIVE" : "OFF"}</Badge>
                    </div>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-[12px] font-bold text-on-surface-variant uppercase border-b border-outline-variant pb-2">Delivery Thresholds</h4>
                    <div className="space-y-1 mt-2">
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Digest Frequency</span>
                       <p className="font-medium text-on-surface">{renderData.notifications.digestFrequency}</p>
                    </div>
                    <div className="space-y-1 mt-4">
                       <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Priority Threshold</span>
                       <p className="font-medium text-on-surface">{renderData.notifications.priorityThreshold.replace("_", " ")}</p>
                    </div>
                  </div>
                </>
             ) : (
                <>
                  <div className="space-y-4">
                    <h4 className="text-[12px] font-bold text-on-surface-variant uppercase border-b border-outline-variant pb-2 mb-4">Channels Enabled</h4>
                    <FormField label="Email Alerts">
                       <Select 
                          value={renderData.notifications.emailAlertsEnabled ? "ON" : "OFF"}
                          onChange={e => setDraftSettings(prev => prev ? {...prev, notifications: {...prev.notifications, emailAlertsEnabled: e.target.value === "ON"}} : null)}
                       >
                          <option value="ON">Enabled</option>
                          <option value="OFF">Disabled</option>
                       </Select>
                    </FormField>
                    <FormField label="In-App Surface Alerts">
                       <Select 
                          value={renderData.notifications.inAppAlertsEnabled ? "ON" : "OFF"}
                          onChange={e => setDraftSettings(prev => prev ? {...prev, notifications: {...prev.notifications, inAppAlertsEnabled: e.target.value === "ON"}} : null)}
                       >
                          <option value="ON">Enabled</option>
                          <option value="OFF">Disabled</option>
                       </Select>
                    </FormField>
                  </div>

                  <div className="space-y-4">
                    <h4 className="text-[12px] font-bold text-on-surface-variant uppercase border-b border-outline-variant pb-2 mb-4">Delivery Thresholds</h4>
                    <FormField label="Digest Frequency">
                       <Select 
                          value={renderData.notifications.digestFrequency}
                          onChange={e => setDraftSettings(prev => prev ? {...prev, notifications: {...prev.notifications, digestFrequency: e.target.value as "DAILY"|"WEEKLY"|"NEVER"}} : null)}
                       >
                          <option value="DAILY">Daily Digest</option>
                          <option value="WEEKLY">Weekly Rollup</option>
                          <option value="NEVER">Never / Realtime Only</option>
                       </Select>
                    </FormField>
                    <FormField label="Priority Threshold (Minimum to Alert)">
                       <Select 
                          value={renderData.notifications.priorityThreshold}
                          onChange={e => setDraftSettings(prev => prev ? {...prev, notifications: {...prev.notifications, priorityThreshold: e.target.value as NotificationPriorityThreshold}} : null)}
                       >
                          <option value="ALL">All Activity</option>
                          <option value="IMPORTANT">Important & Critical</option>
                          <option value="CRITICAL_ONLY">Critical Only</option>
                          <option value="NONE">Muted Completely</option>
                       </Select>
                    </FormField>
                  </div>
                </>
             )}

           </div>
        </Card>
      </section>

      {/* -------------------- SYSTEM BEHAVIORS -------------------- */}
      <section>
        <div className="flex items-center gap-2 mb-4">
           <span className="material-symbols-outlined text-on-surface-variant text-[20px]">lan</span>
           <h2 className="text-[14px] uppercase font-bold tracking-wider text-on-surface-variant">System Behaviors</h2>
        </div>
        <Card className="p-6 md:p-8">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {!isEditing ? (
                 <>
                   <div className="space-y-1">
                     <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Timezone Rendering</span>
                     <p className="font-medium text-on-surface text-[14.5px]">{renderData.system.defaultTimezone}</p>
                   </div>
                   <div className="space-y-1">
                     <span className="block text-[11px] font-bold text-on-surface-variant uppercase">Auto-Delegation Routing</span>
                     <p className="font-medium text-on-surface flex items-center gap-2 text-[14.5px]">
                       {renderData.system.enableAutoDelegationRouting ? (
                          <><span className="w-2 h-2 rounded-full bg-success"></span> Enabled</>
                       ) : (
                          <><span className="w-2 h-2 rounded-full bg-outline"></span> Disabled</>
                       )}
                     </p>
                   </div>
                   <div className="space-y-1 md:col-span-2 mt-2">
                     <span className="block text-[11px] font-bold text-on-surface-variant uppercase">AI Intelligence Aggressiveness</span>
                     <p className="font-medium text-on-surface text-[14.5px]">{renderData.system.intelligenceAggressiveness}</p>
                     <p className="text-[13px] text-on-surface-variant mt-1.5 max-w-[600px]">Controls how proactive the system is at generating read-only intelligence signals across operational modules regarding risks and required actions.</p>
                   </div>
                 </>
              ) : (
                 <>
                   <FormField label="Timezone Rendering">
                     <Select 
                        value={renderData.system.defaultTimezone}
                        onChange={e => setDraftSettings(prev => prev ? {...prev, system: {...prev.system, defaultTimezone: e.target.value}} : null)}
                     >
                        <option value="America/New_York">America/New_York (EST)</option>
                        <option value="America/Chicago">America/Chicago (CST)</option>
                        <option value="America/Denver">America/Denver (MST)</option>
                        <option value="America/Los_Angeles">America/Los_Angeles (PST)</option>
                        <option value="Europe/London">Europe/London (GMT)</option>
                        <option value="UTC">Coordinated Universal Time (UTC)</option>
                     </Select>
                   </FormField>
                   <FormField label="Auto-Delegation Routing">
                     <Select 
                        value={renderData.system.enableAutoDelegationRouting ? "ON" : "OFF"}
                        onChange={e => setDraftSettings(prev => prev ? {...prev, system: {...prev.system, enableAutoDelegationRouting: e.target.value === "ON"}} : null)}
                     >
                        <option value="ON">Enabled - Enact automated task handoffs</option>
                        <option value="OFF">Disabled - Strictly manual task routing</option>
                     </Select>
                   </FormField>
                   <div className="md:col-span-2">
                     <FormField label="AI Intelligence Aggressiveness">
                       <Select 
                          value={renderData.system.intelligenceAggressiveness}
                          onChange={e => setDraftSettings(prev => prev ? {...prev, system: {...prev.system, intelligenceAggressiveness: e.target.value as "CONSERVATIVE"|"BALANCED"|"PROACTIVE"}} : null)}
                       >
                          <option value="CONSERVATIVE">CONSERVATIVE - Only critical risk flags generated</option>
                          <option value="BALANCED">BALANCED - Standard recommendations and context signals</option>
                          <option value="PROACTIVE">PROACTIVE - Aggressively identifies pipeline optimizations</option>
                       </Select>
                     </FormField>
                   </div>
                 </>
              )}
           </div>
        </Card>
      </section>

    </div>
  );
}
